// #region 🎼Utilities

// Generic utility and type definitions that make @semio-tech/ui-react self-contained.
// These MUST NOT depend on any external compose package.

/**
 * Merges CSS class names using Tailwind merge.
 **/
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// #region 🔖SelectionMarquee
/** @emoji ⬚ Canonical area-select overlay coverage (drag right-to-left = partial). */
export type SelectionMarqueeCoverage = "partial" | "full";

export type SelectionMarqueeRect = {
  readonly x: number | string;
  readonly y: number | string;
  readonly width: number | string;
  readonly height: number | string;
};

export type SelectionMarqueePoint = {
  readonly x: number;
  readonly y: number;
};

export type SelectionMarqueeProps = {
  readonly coverage: SelectionMarqueeCoverage;
  readonly className?: string;
} & ({ readonly shape: "rect"; readonly rect: SelectionMarqueeRect } | { readonly shape: "polygon"; readonly points: readonly SelectionMarqueePoint[] });

/** @emoji ⬚ Shared SVG marquee for spatial area selection (primary fill/stroke; dashed when partial). */
export function SelectionMarquee(props: SelectionMarqueeProps): React.ReactElement {
  const { coverage, className } = props;
  const svgClass = cn("selection-marquee pointer-events-none absolute inset-0 h-full w-full overflow-visible", className);
  if (props.shape === "rect") {
    const { rect } = props;
    return (
      <svg className={svgClass} data-coverage={coverage} aria-hidden>
        <rect x={rect.x} y={rect.y} width={rect.width} height={rect.height} />
      </svg>
    );
  }
  const points = props.points.map((point) => `${point.x},${point.y}`).join(" ");
  return (
    <svg className={svgClass} data-coverage={coverage} aria-hidden>
      <polygon points={points} />
    </svg>
  );
}

export type SelectionMergeMode = "default" | "additive" | "subtractive" | "invertive";

export const SELECTION_DRAG_DIRECTION_THRESHOLD_PX = 2;

export type SelectionMarqueeMethod = "lasso" | "rectangle";

/** @emoji 🖱️ Crossing selection when the drag ends left of the start (partial overlap). */
export function marqueeIsCrossing(startX: number, endX: number): boolean {
  return endX < startX;
}

/** @emoji 🖱️ Lasso uses the first horizontal step; rectangle compares start vs end. */
export function marqueeIsCrossingFromPath(path: readonly SelectionMarqueePoint[], method: SelectionMarqueeMethod = "rectangle"): boolean {
  const start = path[0];
  if (!start) return false;
  if (method === "lasso") {
    for (const point of path.slice(1)) {
      const dx = point.x - start.x;
      if (Math.abs(dx) < SELECTION_DRAG_DIRECTION_THRESHOLD_PX) continue;
      return dx < 0;
    }
  }
  const end = path[path.length - 1] ?? start;
  return marqueeIsCrossing(start.x, end.x);
}

/** @emoji 🖱️ Maps drag direction to marquee coverage (rectangle endpoints). */
export function marqueeCoverageFromDrag(startX: number, endX: number): SelectionMarqueeCoverage {
  return marqueeIsCrossing(startX, endX) ? "partial" : "full";
}

/** @emoji 🖱️ Maps gesture path to marquee coverage (lasso first horizontal step). */
export function marqueeCoverageFromPath(path: readonly SelectionMarqueePoint[], method: SelectionMarqueeMethod = "rectangle"): SelectionMarqueeCoverage {
  return marqueeIsCrossingFromPath(path, method) ? "partial" : "full";
}

/** @emoji 🖱️ Resolves marquee coverage for rectangle or lasso gestures. */
export function marqueeCoverageFromGesture(input: { readonly method: SelectionMarqueeMethod; readonly startX: number; readonly endX: number; readonly path: readonly SelectionMarqueePoint[] }): SelectionMarqueeCoverage {
  if (input.method === "lasso" && input.path.length > 0) {
    return marqueeCoverageFromPath(input.path, "lasso");
  }
  return marqueeCoverageFromDrag(input.startX, input.endX);
}

/** @emoji 🎯 Maps shift/ctrl modifiers to marquee selection mode (ctrl+shift → invertive). */
export function marqueeModeFromModifiers(modifiers: { readonly shiftKey?: boolean; readonly ctrlKey?: boolean; readonly metaKey?: boolean }): SelectionMergeMode {
  const globalMode = (globalThis as any).__selectionMode;
  if (globalMode && globalMode !== "default") {
    return globalMode;
  }
  const shift = modifiers.shiftKey === true;
  const ctrl = modifiers.ctrlKey === true || modifiers.metaKey === true;
  if (shift && ctrl) return "invertive";
  if (shift) return "additive";
  if (ctrl) return "subtractive";
  return "default";
}

/** @emoji 🎯 Applies selection mode when committing ids. */
export function selectionMergeIds(mode: SelectionMergeMode, current: readonly string[], incoming: readonly string[]): string[] {
  const currentSet = new Set(current);
  const incomingSet = new Set(incoming);
  if (mode === "default") return [...incomingSet];
  if (mode === "additive") {
    for (const id of incomingSet) currentSet.add(id);
    return [...currentSet];
  }
  if (mode === "subtractive") {
    for (const id of incomingSet) currentSet.delete(id);
    return [...currentSet];
  }
  for (const id of incomingSet) {
    if (currentSet.has(id)) currentSet.delete(id);
    else currentSet.add(id);
  }
  return [...currentSet];
}

export type ScreenRect = { readonly x: number; readonly y: number; readonly width: number; readonly height: number };

export function screenRectContainsRect(outer: ScreenRect, inner: ScreenRect): boolean {
  return inner.x >= outer.x && inner.y >= outer.y && inner.x + inner.width <= outer.x + outer.width && inner.y + inner.height <= outer.y + outer.height;
}

export function screenRectIntersectsRect(a: ScreenRect, b: ScreenRect): boolean {
  return a.x <= b.x + b.width && a.x + a.width >= b.x && a.y <= b.y + b.height && a.y + a.height >= b.y;
}

export function screenRectFromPoints(points: readonly { readonly x: number; readonly y: number }[]): ScreenRect | null {
  if (!points.length) return null;
  const xs = points.map((point) => point.x);
  const ys = points.map((point) => point.y);
  const minX = Math.min(...xs);
  const minY = Math.min(...ys);
  const maxX = Math.max(...xs);
  const maxY = Math.max(...ys);
  return { x: minX, y: minY, width: maxX - minX, height: maxY - minY };
}
// #endregion 🔖SelectionMarquee

// #region 🔖CanvasPickMenu
export type CanvasPickMenuProps = {
  readonly request: CanvasPickRequest | null;
  readonly hoveredKey: string | null;
  readonly onHoverKey: (key: string | null) => void;
  readonly onPick: (target: CanvasPickTarget) => void;
  readonly onDismiss: () => void;
  readonly renderRow?: (target: CanvasPickTarget, active: boolean) => React.ReactNode;
  readonly title?: string;
};

export { CANVAS_HOVER_SOURCE_CANVAS, CANVAS_HOVER_SOURCE_PICK_MENU, canvasHoverFocusFromTarget, canvasPickTargetKey, pickMostSpecificCanvasTarget, sortCanvasPickTargetsGeneralFirst } from "@semio-tech/framework-core";
export type { CanvasHoverFocus, CanvasPickRequest, CanvasPickTarget } from "@semio-tech/framework-core";

/** @emoji 🎯 Fixed DOM pick list for overlapping canvas targets (not painted on the infinite canvas). */
export function CanvasPickMenu({ request, hoveredKey, onHoverKey, onPick, onDismiss, renderRow, title }: CanvasPickMenuProps): React.ReactNode {
  const menuRef = React.useRef<HTMLDivElement | null>(null);
  const selectTargetLabel = useLabel("ui.common.selectTarget");
  const resolvedTitle = title ?? selectTargetLabel;

  React.useEffect(() => {
    if (!request) return;
    const onPointerDown = (event: PointerEvent) => {
      const menu = menuRef.current;
      if (menu?.contains(event.target as globalThis.Node)) return;
      onDismiss();
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onDismiss();
    };
    window.addEventListener("pointerdown", onPointerDown, true);
    window.addEventListener("keydown", onKeyDown, true);
    return () => {
      window.removeEventListener("pointerdown", onPointerDown, true);
      window.removeEventListener("keydown", onKeyDown, true);
    };
  }, [onDismiss, request]);

  if (!request || request.targets.length === 0) return null;
  const sorted = sortCanvasPickTargetsGeneralFirst(request.targets);
  const body = sorted.map((target) => {
    const key = canvasPickTargetKey(target);
    const active = hoveredKey === key;
    return (
      <button
        key={key}
        type="button"
        role="menuitem"
        aria-selected={active}
        className={cn(floatingMenuItemClass, active && "bg-active-base text-emphasized")}
        onPointerEnter={() => onHoverKey(key)}
        onPointerLeave={() => onHoverKey(null)}
        onPointerDown={(event) => {
          event.preventDefault();
          event.stopPropagation();
          onPick(target);
        }}
      >
        {renderRow ? (
          renderRow(target, active)
        ) : (
          <>
            <span className="text-muted-foreground">{target.domain}</span> <code className="text-foreground">{target.label ?? target.id}</code>
          </>
        )}
      </button>
    );
  });
  if (typeof document === "undefined") return null;
  return createPortal(
    <div
      ref={menuRef}
      role="menu"
      className={cn("fixed z-tutorial w-layout-floating-menu-sm max-h-layout-preview-md overflow-y-auto p-single", floatingMenuSurfaceClass)}
      style={{
        left: Math.min(request.client.x + 8, window.innerWidth - 230),
        top: Math.min(request.client.y + 8, window.innerHeight - 220),
      }}
      onPointerDown={(event) => event.stopPropagation()}
    >
      <div className="text-muted-foreground px-single py-half text-2xs">{resolvedTitle}</div>
      {body}
    </div>,
    document.body,
  );
}

export type UseCanvasPickInteractionOptions = {
  readonly resolveTargetsAtClient: (client: { readonly x: number; readonly y: number }) => readonly CanvasPickTarget[];
  readonly onHoverFocus: (focus: CanvasHoverFocus) => void;
  readonly onSelectTarget: (target: CanvasPickTarget, request: CanvasPickRequest) => void;
  readonly clickThresholdPx?: number;
};

export type CanvasPickInteraction = {
  readonly pickMenu: CanvasPickRequest | null;
  readonly menuHoveredKey: string | null;
  readonly pickMenuOpen: boolean;
  readonly onCanvasPointerDown: (client: { readonly x: number; readonly y: number }) => void;
  readonly onCanvasPointerMove: (client: { readonly x: number; readonly y: number }) => void;
  readonly onCanvasPointerLeave: () => void;
  readonly onCanvasPointerUp: (client: { readonly x: number; readonly y: number }, modifiers?: Readonly<Record<string, boolean>>) => void;
  readonly dismissPickMenu: () => void;
  readonly onMenuHoverKey: (key: string | null) => void;
  readonly onMenuPick: (target: CanvasPickTarget) => void;
};

/** @emoji 🎯 Shared pointer routing for canvas hover (most-specific) and click disambiguation menus. */
export function useCanvasPickInteraction({ resolveTargetsAtClient, onHoverFocus, onSelectTarget, clickThresholdPx = 4 }: UseCanvasPickInteractionOptions): CanvasPickInteraction {
  const [pickMenu, setPickMenu] = React.useState<CanvasPickRequest | null>(null);
  const [menuHoveredKey, setMenuHoveredKey] = React.useState<string | null>(null);
  const pointerDownRef = React.useRef<{ readonly x: number; readonly y: number } | null>(null);

  const dismissPickMenu = React.useCallback(() => {
    setPickMenu(null);
    setMenuHoveredKey(null);
    onHoverFocus(canvasHoverFocusFromTarget(CANVAS_HOVER_SOURCE_CANVAS, null));
  }, [onHoverFocus]);

  const onCanvasPointerMove = React.useCallback(
    (client: { readonly x: number; readonly y: number }) => {
      if (pickMenu) return;
      const targets = resolveTargetsAtClient(client);
      const specific = pickMostSpecificCanvasTarget(targets);
      onHoverFocus(canvasHoverFocusFromTarget(CANVAS_HOVER_SOURCE_CANVAS, specific));
    },
    [onHoverFocus, pickMenu, resolveTargetsAtClient],
  );

  const onCanvasPointerLeave = React.useCallback(() => {
    if (pickMenu) return;
    onHoverFocus(canvasHoverFocusFromTarget(CANVAS_HOVER_SOURCE_CANVAS, null));
  }, [onHoverFocus, pickMenu]);

  const onCanvasPointerDown = React.useCallback((client: { readonly x: number; readonly y: number }) => {
    pointerDownRef.current = client;
  }, []);

  const onCanvasPointerUp = React.useCallback(
    (client: { readonly x: number; readonly y: number }, modifiers: Readonly<Record<string, boolean>> = {}) => {
      const start = pointerDownRef.current;
      pointerDownRef.current = null;
      if (start) {
        const dx = client.x - start.x;
        const dy = client.y - start.y;
        if (Math.hypot(dx, dy) > clickThresholdPx) return;
      }
      const targets = resolveTargetsAtClient(client);
      if (targets.length === 0) {
        dismissPickMenu();
        return;
      }
      if (targets.length === 1) {
        dismissPickMenu();
        onSelectTarget(targets[0]!, { targets, client, modifiers });
        return;
      }
      const request: CanvasPickRequest = { targets, client, modifiers };
      setPickMenu(request);
      const first = sortCanvasPickTargetsGeneralFirst(targets)[0]!;
      const key = canvasPickTargetKey(first);
      setMenuHoveredKey(key);
      onHoverFocus(canvasHoverFocusFromTarget(CANVAS_HOVER_SOURCE_PICK_MENU, first));
    },
    [clickThresholdPx, dismissPickMenu, onHoverFocus, onSelectTarget, resolveTargetsAtClient],
  );

  const onMenuHoverKey = React.useCallback(
    (key: string | null) => {
      setMenuHoveredKey(key);
      if (!pickMenu) return;
      const target = key ? (pickMenu.targets.find((row) => canvasPickTargetKey(row) === key) ?? null) : null;
      onHoverFocus(canvasHoverFocusFromTarget(CANVAS_HOVER_SOURCE_PICK_MENU, target));
    },
    [onHoverFocus, pickMenu],
  );

  const onMenuPick = React.useCallback(
    (target: CanvasPickTarget) => {
      if (!pickMenu) return;
      onSelectTarget(target, pickMenu);
      dismissPickMenu();
    },
    [dismissPickMenu, onSelectTarget, pickMenu],
  );

  return {
    pickMenu,
    menuHoveredKey,
    pickMenuOpen: pickMenu !== null,
    onCanvasPointerMove,
    onCanvasPointerLeave,
    onCanvasPointerUp,
    dismissPickMenu,
    onMenuHoverKey,
    onMenuPick,
    onCanvasPointerDown,
  };
}
// #endregion 🔖CanvasPickMenu

// #region 🔖Icon
/** @emoji 📐 Named size tokens for {@link Icon}. */
export type IconSizeToken = "tiny" | "small" | "base" | "large";

const ICON_SIZE_PX: Record<IconSizeToken, number> = {
  tiny: domSizePx("iconTinyUiSpacing"),
  small: domSizePx("iconSmallUiSpacing"),
  base: domSizePx("iconBaseUiSpacing"),
  large: domSizePx("iconLargeUiSpacing"),
};

/** @emoji 📐 Resolves {@link Icon} `size` to pixel dimensions. */
export function resolveIconSizePx(size?: number | IconSizeToken): number {
  if (size === undefined) return ICON_SIZE_PX.base;
  if (typeof size === "number") return size;
  return ICON_SIZE_PX[size];
}

// #region 🖼️IconCodec

/** @emoji 🖼 Canonical structured icon payload shared across canvases and UI chrome. */
export type Icon =
  | { readonly kind: "url"; readonly url: string }
  | { readonly kind: "shortcode"; readonly code: string }
  | { readonly kind: "data"; readonly data: string }
  | { readonly kind: "emoji"; readonly emoji: string }
  | { readonly kind: "typst"; readonly src: string }
  | { readonly kind: "text"; readonly text: string }
  | { readonly kind: "svg"; readonly svg: string }
  | { readonly kind: "catalog"; readonly key: IconName }
  | { readonly kind: "themed"; readonly key: MetabolismIconName }
  | { readonly kind: "node"; readonly node: React.ReactNode };

/** @emoji 🎛 Shared icon editor tab buckets aligned with {@link Icon}. */
export type IconSelectorMode = "url" | "shortcode" | "data" | "emoji" | "math" | "text" | "vector";

function isRasterDataUrlPayloadForIcon(s: string): boolean {
  const u = s.trim().toLowerCase();
  return u.startsWith("data:image/png;base64,") || u.startsWith("data:image/jpeg;base64,") || u.startsWith("data:image/jpg;base64,") || u.startsWith("data:image/webp;base64,") || u.startsWith("data:image/gif;base64,");
}

function isSvgDataUrlPayloadForIcon(s: string): boolean {
  return s.trim().toLowerCase().startsWith("data:image/svg+xml");
}

function looksLikeShortcodeToken(t: string): boolean {
  return t.length >= 3 && t.startsWith(":") && t.endsWith(":") && /^:[\w+-]+:$/.test(t);
}

function looksLikeAsciiCatalogishStemForIcon(s: string): boolean {
  const t = s.trim();
  if (t === "" || !/^[\w.-]+$/.test(t)) {
    return false;
  }
  return /[._-]/.test(t) || t.length > 48;
}

function looksLikeBareUrlForIcon(s: string): boolean {
  const lower = s.trim().toLowerCase();
  return lower.startsWith("http://") || lower.startsWith("https://");
}

function looksLikeBareEmojiForIcon(s: string): boolean {
  return /\p{Extended_Pictographic}/u.test(s.trim());
}

/** @emoji 🔤 Decodes a canonical icon string into a structured {@link Icon}. */
export function decodeIcon(encoded: string): Icon | undefined {
  const t = encoded.trim();
  if (t === "") {
    return undefined;
  }
  if (t.startsWith("url:")) {
    const url = t.slice("url:".length).trim();
    return url === "" ? undefined : { kind: "url", url };
  }
  if (looksLikeBareUrlForIcon(t)) {
    return { kind: "url", url: t };
  }
  if (looksLikeShortcodeToken(t)) {
    return { kind: "shortcode", code: t.slice(1, -1) };
  }
  if (t.startsWith("typst:")) {
    const src = t.slice("typst:".length).trim();
    return src === "" ? undefined : { kind: "typst", src };
  }
  if (t.startsWith("$")) {
    return { kind: "typst", src: t };
  }
  if (t.startsWith("emoji:")) {
    const emoji = t.slice("emoji:".length).trim();
    return emoji === "" ? undefined : { kind: "emoji", emoji };
  }
  if (t.startsWith("text:")) {
    const text = t.slice("text:".length).trim();
    return text === "" ? undefined : { kind: "text", text };
  }
  if (isRasterDataUrlPayloadForIcon(t) || isSvgDataUrlPayloadForIcon(t) || t.toLowerCase().startsWith("data:")) {
    return { kind: "data", data: t };
  }
  const lower = t.toLowerCase();
  if (lower.startsWith("<?xml") || lower.includes("<svg")) {
    return { kind: "svg", svg: t };
  }
  if (isMetabolismIconName(t)) {
    return { kind: "themed", key: t };
  }
  if (isIconName(t)) {
    return { kind: "catalog", key: t };
  }
  if (looksLikeAsciiCatalogishStemForIcon(t)) {
    return undefined;
  }
  if (looksLikeBareEmojiForIcon(t)) {
    return { kind: "emoji", emoji: t };
  }
  if ([...t].length <= 16) {
    return { kind: "text", text: t };
  }
  return undefined;
}

/** @emoji 🔤 Encodes a structured {@link Icon} into the canonical wire string. */
export function encodeIcon(icon: Icon): string {
  switch (icon.kind) {
    case "url":
      return `url:${icon.url.trim()}`;
    case "shortcode":
      return `:${icon.code.trim()}:`;
    case "data":
      return icon.data.trim();
    case "emoji":
      return `emoji:${icon.emoji.trim()}`;
    case "typst":
      return icon.src.trim().startsWith("$") ? icon.src.trim() : `typst:${icon.src.trim()}`;
    case "text":
      return `text:${icon.text.trim()}`;
    case "svg":
      return icon.svg.trim();
    case "catalog":
      return icon.key;
    case "themed":
      return icon.key;
    case "node":
      return "";
  }
}

/** @emoji 🧭 Picks an {@link IconSelectorMode} tab for a stored icon string. */
export function classifyIconSelectorMode(raw: string): IconSelectorMode {
  const icon = decodeIcon(raw);
  if (!icon) {
    return "math";
  }
  switch (icon.kind) {
    case "url":
      return "url";
    case "shortcode":
      return "shortcode";
    case "data":
      return "data";
    case "emoji":
      return "emoji";
    case "typst":
      return "math";
    case "text":
      return "text";
    case "svg":
    case "catalog":
    case "themed":
      return "vector";
    case "node":
      return "vector";
  }
}

function resolveShortcodeIcon(code: string): Icon {
  const key = code.trim();
  const lower = key.toLowerCase();
  const emoji = shortcodeEmoji(lower);
  if (emoji) {
    return { kind: "emoji", emoji };
  }
  const catalog = shortcodeCatalogKey(key);
  if (catalog) {
    return { kind: "catalog", key: catalog };
  }
  return { kind: "shortcode", code: key };
}

const iconUrlDataCache = new Map<string, string>();

async function fetchIconUrlAsDataUrl(url: string): Promise<string | undefined> {
  const cached = iconUrlDataCache.get(url);
  if (cached) {
    return cached;
  }
  try {
    const res = await fetch(url);
    if (!res.ok) {
      return undefined;
    }
    const blob = await res.blob();
    const data = await new Promise<string>((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(typeof reader.result === "string" ? reader.result : "");
      reader.onerror = () => reject(reader.error);
      reader.readAsDataURL(blob);
    });
    const trimmed = data.trim();
    if (trimmed !== "") {
      iconUrlDataCache.set(url, trimmed);
    }
    return trimmed || undefined;
  } catch {
    return undefined;
  }
}

/** @emoji 🌐 Prefetches `url:`/`http(s)` icons in board JSON to inline `data:` payloads before WASM sync. */
export async function resolveIconUrlsInBoardJson(json: string): Promise<string> {
  let root: unknown;
  try {
    root = JSON.parse(json);
  } catch {
    return json;
  }
  if (!root || typeof root !== "object") {
    return json;
  }
  const record = root as Record<string, unknown>;
  const pending: Promise<void>[] = [];
  const visit = (iconKind: unknown, apply: (next: string) => void) => {
    if (typeof iconKind !== "string" || iconKind.trim() === "") {
      return;
    }
    const icon = decodeIcon(iconKind);
    if (!icon || icon.kind !== "url") {
      return;
    }
    const cached = iconUrlDataCache.get(icon.url);
    if (cached) {
      apply(cached);
      return;
    }
    pending.push(
      fetchIconUrlAsDataUrl(icon.url).then((data) => {
        if (data) {
          apply(data);
        }
      }),
    );
  };
  for (const bucket of ["nodes", "handles"] as const) {
    const rows = record[bucket];
    if (!Array.isArray(rows)) {
      continue;
    }
    for (const row of rows) {
      if (!row || typeof row !== "object") {
        continue;
      }
      const obj = row as Record<string, unknown>;
      visit(obj.iconKind, (next) => {
        obj.iconKind = next;
      });
    }
  }
  if (pending.length === 0) {
    return json;
  }
  await Promise.all(pending);
  return JSON.stringify(root);
}

/** @emoji 🖼 Icon payload: canonical union, vendored catalog name, or legacy shorthand. */
export type IconSource = Icon | IconName | { readonly name: IconName } | { readonly svg: string } | { readonly url: string } | { readonly node: React.ReactNode };

/** @emoji 🎛 Required icon slot for chrome controls (buttons, toggles, actions). */
export type ControlIcon = IconSource | React.ReactElement;

function isIconSource(value: ControlIcon): value is IconSource {
  if (typeof value === "string") return true;
  if (typeof value === "object" && value !== null && !React.isValidElement(value)) {
    return "kind" in value || "name" in value || "svg" in value || "url" in value || "node" in value;
  }
  return false;
}

function useThemeIcons(): UiTheme["icons"] {
  return React.useSyncExternalStore(
    subscribeActiveUiTheme,
    () => activeUiTheme().icons,
    () => activeUiTheme().icons,
  );
}

/** @emoji 🖼 Resolves catalog icon SVG for the active theme. */
export function resolveCatalogIconSvg(name: IconName, icons: UiTheme["icons"] = activeUiTheme().icons): string {
  return resolveCatalogIconSvgFromTheme(name, icons);
}

/** @emoji 🖼 Resolves metabolism icon SVG for the active theme. */
export function resolveMetabolismIconSvg(name: MetabolismIconName, icons: UiTheme["icons"] = activeUiTheme().icons): string {
  return resolveMetabolismIconSvgFromTheme(name, icons);
}

const CATALOG_ICON_ALIASES: Partial<Record<string, IconName>> = {
  trash: "trash-2",
};

function coerceIconSource(source: IconSource): Icon {
  if (typeof source === "string") {
    const key = source.trim();
    const alias = CATALOG_ICON_ALIASES[key];
    if (alias) {
      return { kind: "catalog", key: alias };
    }
    if ((ICONS as Record<string, string>)[key]) {
      return { kind: "catalog", key };
    }
    const emoji = shortcodeEmoji(key.toLowerCase());
    if (emoji) {
      return { kind: "emoji", emoji };
    }
    const catalog = shortcodeCatalogKey(key);
    if (catalog) {
      return { kind: "catalog", key: catalog };
    }
    const decoded = decodeIcon(key);
    if (decoded) {
      return decoded;
    }
    return { kind: "text", text: key };
  }
  if ("kind" in source) {
    return source;
  }
  if ("node" in source) {
    return { kind: "node", node: source.node };
  }
  if ("svg" in source) {
    return { kind: "svg", svg: source.svg };
  }
  if ("url" in source) {
    return { kind: "url", url: source.url };
  }
  return { kind: "catalog", key: source.name };
}

/** @emoji 🎛 Renders a control icon or a visible missing-icon placeholder. */
export function renderControlIcon(icon: ControlIcon | undefined | null | false, size: number | IconSizeToken = "small"): React.ReactNode {
  if (icon === undefined || icon === null || icon === false) {
    return <span data-missing-icon data-icon-kind="missing" className="inline-flex size-small shrink-0 rounded-sm bg-destructive/30" aria-hidden />;
  }
  if (isIconSource(icon)) return <Icon icon={icon} size={size} />;
  return icon;
}

export interface IconProps {
  icon: IconSource;
  size?: number | IconSizeToken;
  className?: string;
  title?: string;
}

/** @emoji 🖼 Raw vendored SVG markup for an icon name, or `undefined` when the name is not a vendored {@link IconName}. */
export function iconSvgMarkup(name: IconName): string {
  return resolveCatalogIconSvg(name);
}

const ICON_SIZE_CLASS: Record<IconSizeToken, string> = {
  tiny: "size-tiny",
  small: "size-small",
  base: "size-workbench",
  large: "size-xl",
};

function iconBoxStyle(size: number | IconSizeToken): React.CSSProperties | undefined {
  if (typeof size !== "number") {
    return undefined;
  }
  return { width: uiSpacingLen(size / (STYLING_COMPACT_ROOT_PX * 0.2)), height: uiSpacingLen(size / (STYLING_COMPACT_ROOT_PX * 0.2)) };
}

function iconBoxClassName(size: number | IconSizeToken, className?: string): string {
  return cn(typeof size === "string" ? ICON_SIZE_CLASS[size] : undefined, className);
}

/** @emoji 🖼 Renders canonical icons without depending on an external icon library. */
export function Icon({ icon, size = "base", className, title }: IconProps): React.ReactElement {
  const themeIcons = useThemeIcons();
  const boxStyle = iconBoxStyle(size);
  const boxClass = iconBoxClassName(size, className);
  let normalized = coerceIconSource(icon);
  if (normalized.kind === "shortcode") {
    normalized = resolveShortcodeIcon(normalized.code);
  }
  if (normalized.kind === "node") {
    return (
      <span data-icon-kind="node" className={cn("inline-flex shrink-0 items-center justify-center", boxClass)} style={boxStyle} title={title}>
        {normalized.node}
      </span>
    );
  }
  if (normalized.kind === "url" || normalized.kind === "data") {
    const src = normalized.kind === "url" ? normalized.url : normalized.data;
    return <img src={src} alt="" data-icon-kind="image" className={cn("shrink-0 object-contain", boxClass)} style={boxStyle} title={title} />;
  }
  if (normalized.kind === "emoji") {
    return (
      <span
        data-icon-kind="emoji"
        className={cn("inline-flex shrink-0 items-center justify-center text-base leading-none", boxClass)}
        style={{ ...boxStyle, fontFamily: "'Noto Color Emoji','Segoe UI Emoji',sans-serif" }}
        title={title}
        aria-hidden={title ? undefined : true}
      >
        {normalized.emoji}
      </span>
    );
  }
  if (normalized.kind === "text" || normalized.kind === "typst") {
    const label = normalized.kind === "text" ? normalized.text : normalized.src;
    return (
      <span data-icon-kind={normalized.kind} className={cn("inline-flex shrink-0 items-center justify-center font-mono text-xs", boxClass)} style={boxStyle} title={title}>
        {label}
      </span>
    );
  }
  const svgMarkup =
    normalized.kind === "svg" ? normalized.svg : normalized.kind === "catalog" ? resolveCatalogIconSvgFromTheme(normalized.key, themeIcons) : normalized.kind === "themed" ? resolveMetabolismIconSvgFromTheme(normalized.key, themeIcons) : undefined;
  if (!svgMarkup) {
    return (
      <span data-icon-kind={normalized.kind === "shortcode" ? "shortcode" : "missing"} className={cn("inline-flex shrink-0 items-center justify-center font-mono text-2xs text-muted-foreground", boxClass)} style={boxStyle} title={title}>
        {normalized.kind === "catalog" || normalized.kind === "themed" ? normalized.key.slice(0, 3) : "?"}
      </span>
    );
  }
  return (
    <span
      className={cn("inline-flex shrink-0 items-center justify-center [&>svg]:size-full", boxClass)}
      style={boxStyle}
      title={title}
      data-icon={normalized.kind === "catalog" ? normalized.key : normalized.kind === "themed" ? normalized.key : undefined}
      data-icon-kind={normalized.kind === "catalog" ? "catalog" : normalized.kind === "themed" ? "themed" : "svg"}
      dangerouslySetInnerHTML={{ __html: svgMarkup }}
      aria-hidden={title ? undefined : true}
    />
  );
}

