/** @emoji 🎨 Shared transition for interactive chrome (hover, focus, active backgrounds). */
export const interactiveControlTransitionClass = "transition-[color,border-color,background-color]";

/** @emoji 🫳 `data-hover-scope` marks the element {@link DragHandle} should toggle `data-handle-hovered` on — the nearest ancestor styled by the `hoverExcludingHandle*`/`groupHoverExcludingHandle*` classes below. */
const HANDLE_HOVER_SCOPE_ATTR = "data-hover-scope";

/**
 * @emoji 🫳 Hover-reactive utilities suppressed while a nested {@link DragHandle} is hovered — hovering the grip
 * then only highlights the grip, not the whole element. Pair with `{HANDLE_HOVER_SCOPE_ATTR}` on the same element
 * (the handle toggles `data-handle-hovered` on its nearest `data-hover-scope` ancestor via plain DOM writes, no
 * re-render). Deliberately avoids `:has()` — it isn't reliably supported across every environment this ships to
 * (older embedded webviews), and `:has()`-based ancestor exclusion also matches ANY ancestor with a matching
 * class, not necessarily the nearest one, which is wrong once tree rows nest.
 *
 * These MUST be written as complete literal strings, not built via `${}` interpolation in a helper function —
 * Tailwind's build only discovers classes by scanning source files for literal text, it never executes JS, so a
 * class name assembled from a template placeholder at runtime is invisible to it and silently generates no CSS
 * at all (this broke hover entirely here once already).
 */
const hoverExcludingHandleBgFillClass = "hover:not-data-[handle-hovered=true]:bg-hover-interactive-fill";
const hoverExcludingHandleTextEmphasizedClass = "hover:not-data-[handle-hovered=true]:text-emphasized";
const hoverExcludingHandleActiveBgClass = "hover:not-data-[handle-hovered=true]:bg-active-base/90";
const hoverExcludingHandleActiveBorderClass = "hover:not-data-[handle-hovered=true]:border-active-base";
const groupHoverExcludingHandleBgFillClass = "group-hover:not-group-data-[handle-hovered=true]:bg-hover-interactive-fill";

/** @emoji 🎨 Normal-border gray fill for interactive hover states. */
export const interactiveHoverFillClass = "hover:bg-hover-interactive-fill";

/** @emoji 🎨 Interactive hover: normal-border fill + emphasized content. */
export const interactiveHoverClass = cn(interactiveHoverFillClass, "hover:text-emphasized");

/** @emoji 📏 Active stroke paired with {@link interactiveActiveFillClass}. */
export const interactiveActiveBorderClass = "border-active-base";

/** @emoji 🌀 Clockwise spinning + pulsing loading ring in the element's normal border color. */
export const loadingBorderClass = "border-loading";

/** @emoji 🌀 Loading ring recolored to the active stroke; pair with selected/active elements. */
export const loadingBorderActiveClass = cn(loadingBorderClass, "border-loading-active");

/** @emoji 🌀 Loading ring in the level-aware element border color. */
export const loadingBorderElementClass = cn(loadingBorderClass, "border-loading-element");

/** @emoji 🌀 Loading ring matching the element's current state color; empty when not loading. */
export function loadingBorderStateClass(loading: boolean, active = false): string {
  return loading ? (active ? loadingBorderActiveClass : loadingBorderClass) : "";
}

/** @emoji 🌀 Dashed, slow-spinning + gently pulsing waiting ring in the element's normal border color. */
export const waitingBorderClass = "border-waiting";

/** @emoji 🌀 Waiting ring recolored to the active stroke; pair with selected/active elements. */
export const waitingBorderActiveClass = cn(waitingBorderClass, "border-waiting-active");

/** @emoji 🌀 Waiting ring in the level-aware element border color. */
export const waitingBorderElementClass = cn(waitingBorderClass, "border-waiting-element");

/** @emoji 🌀 Waiting ring matching the element's current state color; empty when not waiting. */
export function waitingBorderStateClass(waiting: boolean, active = false): string {
  return waiting ? (active ? waitingBorderActiveClass : waitingBorderClass) : "";
}

/** @emoji 🎨 Active/on: primary fill + active border + emphasized content (never the transient hover fill). */
export const interactiveOnClass = cn(
  "data-[state=on]:bg-active-base",
  "data-[state=on]:border-active-base",
  "data-[state=on]:text-emphasized",
  "data-[state=on]:hover:bg-active-base/90",
  "data-[state=on]:hover:border-active-base",
  "data-[state=on]:hover:text-emphasized",
);

/** @emoji 🎨 Shared active fill for pressed tabs, toggles, and nav selection. */
export const interactiveActiveFillClass = cn("bg-active-base", interactiveActiveBorderClass, "text-emphasized", hoverExcludingHandleActiveBgClass, hoverExcludingHandleActiveBorderClass, hoverExcludingHandleTextEmphasizedClass);

/** @emoji 🎨 Table rows: element gray at rest, hover fill + emphasized content. */
export const tableRowInteractiveClass = cn("text-element", interactiveControlTransitionClass, interactiveHoverClass);

/** @emoji 🎨 Selected table row: primary fill + emphasized content. */
export const tableRowSelectedClass = interactiveActiveFillClass;

/** @emoji 🎨 Active tab: primary fill + active border + emphasized content. */
export const interactiveTabActiveClass = cn(
  "data-[state=active]:bg-active-base",
  "data-[state=active]:border-active-base",
  "data-[state=active]:text-emphasized",
  "data-[state=active]:hover:bg-active-base/90",
  "data-[state=active]:hover:border-active-base",
  "data-[state=active]:hover:text-emphasized",
);

/** @emoji 📋 Hover row styling for menus, selects, comboboxes, and context menus. */
export const menuListItemClassName = cn(
  "text-element",
  interactiveHoverClass,
  "focus:bg-hover-interactive-fill focus:text-emphasized",
  "data-[selected=true]:bg-active-base data-[selected=true]:border-active-base data-[selected=true]:text-emphasized",
);

const contextMenuShortcutClassName = "ms-auto text-xs text-muted-foreground ps-tiny";

/** @emoji 🪟 Context-menu surface — window-chrome wrapper around menu rows. */
function contextMenuContentClassName(...extra: Array<string | false | null | undefined>): string {
  return cn("z-menu w-auto min-w-[10rem]", ...extra);
}

/** @emoji 🪟 Context-menu row — same density as {@link floatingMenuItemClass}; `checked` paints the active/preview highlight (no tick/checkmark), kept through hover like {@link CanvasPickMenu}. */
function contextMenuItemClassName(item: Pick<ContextMenuItem, "checked" | "destructive">, ...extra: Array<string | false | null | undefined>): string {
  return cn(
    floatingMenuItemClass,
    "whitespace-nowrap data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
    item.destructive && "text-destructive focus:bg-destructive/10 hover:bg-destructive/10",
    ...extra,
    item.checked && "bg-active-base text-emphasized hover:bg-active-base/90 hover:text-emphasized",
  );
}

/**
 * 🧩 Serializable right-click entry for {@link ContextMenu} and puzzle 2d/window surfaces.
 **/
export interface ContextMenuItem {
  id: string;
  label?: string;
  icon?: IconSource | string;
  color?: string;
  shortcut?: string;
  disabled?: boolean;
  separator?: boolean;
  checked?: boolean;
  destructive?: boolean;
  onSelect?: (event: Event) => void;
  onHover?: () => void;
  onHoverEnd?: () => void;
  children?: ContextMenuItem[];
}

function renderContextMenuColor(color: string | undefined): React.ReactNode {
  if (!color) {
    return null;
  }
  return <span aria-hidden className="size-small shrink-0 rounded-sm border border-border" style={{ background: color }} />;
}

function renderContextMenuIcon(icon: ContextMenuItem["icon"]): React.ReactNode {
  if (!icon) {
    return null;
  }
  return <Icon icon={icon as IconSource} size="small" className="shrink-0" />;
}

function renderContextMenuLeading(item: ContextMenuItem): React.ReactNode {
  return (
    <>
      {renderContextMenuColor(item.color)}
      {renderContextMenuIcon(item.icon)}
    </>
  );
}

/**
 * 🧩 Recursively renders {@link ContextMenuItem} rows for Radix dropdown menu surfaces (right-click host).
 **/
export function renderContextMenuItems(items: readonly ContextMenuItem[] | undefined, onClose?: () => void): React.ReactNode {
  if (!items?.length) {
    return null;
  }
  const rows: React.ReactNode[] = [];
  for (const item of items) {
    if (item.separator) {
      rows.push(<DropdownMenuPrimitive.Separator key={`${item.id}-sep`} className="h-px bg-border my-single" />);
      continue;
    }
    if (item.children?.length) {
      rows.push(
        <DropdownMenuPrimitive.Sub key={item.id}>
          <DropdownMenuPrimitive.SubTrigger disabled={item.disabled} className={contextMenuItemClassName(item)}>
            {renderContextMenuLeading(item)}
            <span className="truncate">{item.label ?? item.id}</span>
            <span className={contextMenuShortcutClassName}>{item.shortcut}</span>
          </DropdownMenuPrimitive.SubTrigger>
          <DropdownMenuPrimitive.Portal>
            <DropdownMenuPrimitive.SubContent data-slot="context-menu-content" className="z-menu border-0 bg-transparent p-0 shadow-none">
              <ContextMenuChrome title={item.label ?? item.id}>{renderContextMenuItems(item.children, onClose)}</ContextMenuChrome>
            </DropdownMenuPrimitive.SubContent>
          </DropdownMenuPrimitive.Portal>
        </DropdownMenuPrimitive.Sub>,
      );
      continue;
    }
    rows.push(
      <DropdownMenuPrimitive.Item
        key={item.id}
        disabled={item.disabled}
        className={contextMenuItemClassName(item)}
        data-selected={item.checked ? "true" : undefined}
        onSelect={(event) => {
          item.onSelect?.(event as unknown as Event);
          onClose?.();
        }}
        onPointerEnter={() => item.onHover?.()}
        onPointerLeave={() => item.onHoverEnd?.()}
      >
        {renderContextMenuLeading(item)}
        <span className="truncate">{item.label ?? item.id}</span>
        {item.shortcut ? <span className={contextMenuShortcutClassName}>{item.shortcut}</span> : null}
      </DropdownMenuPrimitive.Item>,
    );
  }
  return <>{rows}</>;
}

type DOMListenerTarget = Pick<EventTarget, "addEventListener" | "removeEventListener">;

function createDOMEventBinding() {
  const cleanups: Array<() => void> = [];
  return {
    listen<E extends Event>(target: DOMListenerTarget | null | undefined, type: string, listener: (event: E) => void, options?: boolean | AddEventListenerOptions) {
      if (!target) return;
      const wrapped = listener as EventListener;
      target.addEventListener(type, wrapped, options);
      cleanups.push(() => target.removeEventListener(type, wrapped, options));
    },
    dispose() {
      while (cleanups.length > 0) cleanups.pop()?.();
    },
  };
}

function getDocumentBody(): HTMLElement | null {
  return typeof document === "undefined" ? null : document.body;
}

function getElementById<T extends HTMLElement = HTMLElement>(id: string): T | null {
  return typeof document === "undefined" ? null : (document.getElementById(id) as T | null);
}

function queryElement<T extends Element = HTMLElement>(selector: string, root?: ParentNode | null): T | null {
  return (root ?? (typeof document === "undefined" ? null : document))?.querySelector(selector) as T | null;
}

function renderPortalInto(children: React.ReactNode, container: Element | DocumentFragment | null | undefined): React.ReactNode {
  return container ? createPortal(children, container) : null;
}

function renderContextMenuTrigger(point: { x: number; y: number } | null): React.ReactNode {
  const trigger = (
    <DropdownMenuPrimitive.Trigger asChild>
      <span
        aria-hidden
        style={{
          height: 1,
          left: point?.x ?? 0,
          opacity: 0,
          pointerEvents: "none",
          position: "fixed",
          top: point?.y ?? 0,
          width: 1,
        }}
      />
    </DropdownMenuPrimitive.Trigger>
  );
  return renderPortalInto(trigger, getDocumentBody()) ?? trigger;
}

export interface ContextMenuProps {
  items?: readonly ContextMenuItem[];
  children: React.ReactNode;
  /** @emoji 🪟 Title chip on the window-chrome cap row. */
  title?: string;
}

/**
 * 🧩 Right-click host: always suppresses the native menu; opens the Radix menu only when `items` is non-empty.
 **/
export const ContextMenu: React.FC<ContextMenuProps> = ({ items, children, title = "Menu" }) => {
  const [open, setOpen] = reactHostPort.useState(false);
  const [point, setPoint] = reactHostPort.useState<{ x: number; y: number } | null>(null);
  const flow = useFlow();
  const close = reactHostPort.useCallback(() => setOpen(false), []);
  const hasItems = !!items?.length;
  const host = (
    <div
      className="contents"
      onContextMenu={(event) => {
        event.preventDefault();
        if (!hasItems) {
          return;
        }
        setPoint({ x: event.clientX, y: event.clientY });
        setOpen(true);
      }}
    >
      {children}
    </div>
  );
  if (!hasItems) {
    return host;
  }
  return (
    <DropdownMenuPrimitive.Root dir={flow.inline === "rtl" ? "rtl" : undefined} modal={false} onOpenChange={setOpen} open={open}>
      {host}
      {renderContextMenuTrigger(point)}
      <DropdownMenuPrimitive.Portal>
        <DropdownMenuPrimitive.Content
          align="start"
          avoidCollisions={false}
          className="z-menu border-0 bg-transparent p-0 shadow-none"
          data-slot="context-menu-content"
          onCloseAutoFocus={(event) => event.preventDefault()}
          side="bottom"
          sideOffset={0}
          style={point ? { left: point.x, position: "fixed", top: point.y } : undefined}
        >
          <ContextMenuChrome title={title}>{renderContextMenuItems(items, close)}</ContextMenuChrome>
        </DropdownMenuPrimitive.Content>
      </DropdownMenuPrimitive.Portal>
    </DropdownMenuPrimitive.Root>
  );
};

export interface ContextMenuControllerProps {
  open: boolean;
  position: { x: number; y: number } | null;
  items: ContextMenuItem[];
  onOpenChange: (open: boolean) => void;
  /** @emoji 🪟 Title chip on the window-chrome cap row. */
  title?: string;
  /** 🖱️ When false, selecting a row does not dismiss — the row action owns closing (e.g. acceptSuggestion). Outside pointer / Escape still dismiss. Default true. */
  closeOnSelect?: boolean;
}

function FixedContextMenuSubmenu({ item, onClose }: { readonly item: ContextMenuItem; readonly onClose: () => void }): React.ReactNode {
  const [open, setOpen] = reactHostPort.useState(false);
  return (
    <div className="relative" onPointerEnter={() => setOpen(true)} onPointerLeave={() => setOpen(false)}>
      <button aria-disabled={item.disabled} className={contextMenuItemClassName(item)} data-disabled={item.disabled ? "" : undefined} data-selected={item.checked ? "true" : undefined} disabled={item.disabled} role="menuitem" type="button">
        {renderContextMenuLeading(item)}
        <span className="truncate">{item.label ?? item.id}</span>
        <span className={contextMenuShortcutClassName}>›</span>
      </button>
      {open && item.children?.length ? (
        <ContextMenuChrome className="absolute start-full top-0 ms-tiny" title={item.label ?? item.id}>
          {renderFixedContextMenuItems(item.children, onClose)}
        </ContextMenuChrome>
      ) : null}
    </div>
  );
}

function renderFixedContextMenuItems(items: ContextMenuItem[], onClose: () => void): React.ReactNode {
  return items.map((item) => {
    if (item.separator) {
      return <div key={`${item.id}-sep`} className="h-px bg-border my-single" role="separator" />;
    }
    if (item.children?.length) {
      return <FixedContextMenuSubmenu key={item.id} item={item} onClose={onClose} />;
    }
    const role = item.checked === undefined ? "menuitem" : "menuitemcheckbox";
    return (
      <button
        key={item.id}
        aria-checked={item.checked}
        aria-disabled={item.disabled}
        className={contextMenuItemClassName(item)}
        data-disabled={item.disabled ? "" : undefined}
        data-selected={item.checked ? "true" : undefined}
        disabled={item.disabled}
        onClick={(event) => {
          item.onSelect?.(event.nativeEvent);
          onClose();
        }}
        onPointerEnter={() => item.onHover?.()}
        onPointerLeave={() => item.onHoverEnd?.()}
        role={role}
        type="button"
      >
        {renderContextMenuLeading(item)}
        <span className="truncate">{item.label ?? item.id}</span>
        {item.shortcut ? <span className={contextMenuShortcutClassName}>{item.shortcut}</span> : null}
      </button>
    );
  });
}

/** @emoji 🖱️ True when a pointer event targets any open context menu surface (including sibling menus from split world panes). */
export function isContextMenuPointerTarget(target: EventTarget | null): boolean {
  return Boolean(target instanceof Element && target.closest('[role="menu"]'));
}

/** @emoji ⌨️ Maps a keydown key to a context-menu digit shortcut (`1`–`9`), if any. */
export function contextMenuDigitFromKey(key: string): string | undefined {
  return key.length === 1 && key >= "1" && key <= "9" ? key : undefined;
}

/** @emoji ⌨️ Finds the first enabled top-level row whose shortcut matches `shortcut`. */
export function findContextMenuItemByShortcut(items: readonly ContextMenuItem[], shortcut: string): ContextMenuItem | undefined {
  return items.find((item) => !item.separator && !item.disabled && item.shortcut === shortcut);
}

/** @emoji ⌨️ Finds the first enabled top-level row marked `checked`. */
export function findCheckedContextMenuItem(items: readonly ContextMenuItem[]): ContextMenuItem | undefined {
  return items.find((item) => !item.separator && !item.disabled && item.checked);
}

/**
 * 🧩 Controlled right-click menu anchored at viewport coordinates (puzzle 2d canvas bridge). Portals to `document.body` for correct `fixed` placement under transformed UI; outside-dismiss uses `window` bubble listeners so they run after the puzzle 2d `eventSurface` bubble path and after `window` capture (441–442 used `document` capture and swallowed input).
 **/
export const ContextMenuController: React.FC<ContextMenuControllerProps> = ({ open, position, items, onOpenChange, title = "Menu", closeOnSelect = true }) => {
  const close = reactHostPort.useCallback(() => onOpenChange(false), [onOpenChange]);
  const flow = useFlow();
  const menuRef = reactHostPort.useRef<HTMLDivElement | null>(null);
  const itemsRef = reactHostPort.useRef(items);
  itemsRef.current = items;
  reactHostPort.useEffect(() => {
    if (!open || !items.length || !position) {
      return undefined;
    }
    // 🛡️ Arm after the opening gesture finishes — opening from another menu's click must not see that
    // same pointer cycle (or a sibling pane's duplicate menu) as an outside dismiss.
    let armed = false;
    const armTimer = window.setTimeout(() => {
      armed = true;
    }, 0);
    const handlePointerDown = (event: PointerEvent): void => {
      if (!armed) return;
      if (isContextMenuPointerTarget(event.target)) return;
      onOpenChange(false);
    };
    const handleKeyDown = (event: KeyboardEvent): void => {
      if (event.key === "Escape") {
        onOpenChange(false);
        return;
      }
      const currentItems = itemsRef.current;
      const digit = contextMenuDigitFromKey(event.key);
      if (digit) {
        const item = findContextMenuItemByShortcut(currentItems, digit);
        if (!item) return;
        event.preventDefault();
        event.stopPropagation();
        if (item.onHover) {
          item.onHover();
          return;
        }
        if (item.onSelect) {
          item.onSelect(new Event("select"));
          if (closeOnSelect) close();
        }
        return;
      }
      if (event.key === "Enter") {
        const item = findCheckedContextMenuItem(currentItems);
        if (!item?.onSelect) return;
        event.preventDefault();
        event.stopPropagation();
        item.onSelect(new Event("select"));
        if (closeOnSelect) close();
      }
    };
    const bindings = createDOMEventBinding();
    bindings.listen(window, "pointerdown", handlePointerDown, false);
    bindings.listen(window, "keydown", handleKeyDown, false);
    return () => {
      window.clearTimeout(armTimer);
      bindings.dispose();
    };
  }, [items.length, onOpenChange, open, position?.x, position?.y]);
  if (!items.length) {
    return null;
  }
  if (!open || !position) {
    return null;
  }
  return renderPortalInto(
    <ContextMenuChrome style={{ left: position.x, position: "fixed", top: position.y }} title={title}>
      <div dir={flow.inline === "rtl" ? "rtl" : undefined} onContextMenu={(event) => event.preventDefault()} ref={menuRef} role="menu">
        {renderFixedContextMenuItems(items, closeOnSelect ? close : () => undefined)}
      </div>
    </ContextMenuChrome>,
    getDocumentBody(),
  );
};

// #endregion 🖱️ContextMenu

// #region 🚗UiDriver
/** @emoji 🏷️ Inline caption policy: full icon+label chrome vs icons only. */
export type UiDriverLabels = "full" | "icons";
/** @emoji 🎚 Which member of a `{normal, beginner}` label pair resolves. */
export type UiDriverLabelTier = "beginner" | "normal";
/** @emoji 🫳 Drag affordance: dedicated grip handle vs whole-element draggable surface. */
export type UiDriverDrag = "handle" | "surface";
/** @emoji 🫥 Chrome/gumball visibility: always painted vs revealed only while the cursor is in the region. */
export type UiDriverReveal = "always" | "hover";
/** @emoji 🎙️ Tooltip richness: full (label + manual/tutorial links + hotkey), minimal (label + hotkey), or none. */
export type UiDriverTooltips = "full" | "minimal" | "none";

/** @emoji 🚗 A named configuration bundle controlling how the UI presents itself. */
export interface UiDriver {
  readonly id: string;
  readonly label: string;
  readonly labels: UiDriverLabels;
  readonly labelTier: UiDriverLabelTier;
  readonly drag: UiDriverDrag;
  readonly chrome: UiDriverReveal;
  readonly gumball: UiDriverReveal;
  readonly tooltips: UiDriverTooltips;
}

/** @emoji 🚗 Every affordance visible: drag handles, full labels, chrome and gumball always painted, rich tooltips. */
export const DEFAULT_UI_DRIVER: UiDriver = { id: "default", label: "Default", labels: "full", labelTier: "normal", drag: "handle", chrome: "always", gumball: "always", tooltips: "full" };
/** @emoji 🚗 Assumes the user knows the UI: icon-only chrome that reveals on hover, whole-surface drag, no tooltips. */
export const COMPACT_UI_DRIVER: UiDriver = { id: "compact", label: "Compact", labels: "icons", labelTier: "normal", drag: "surface", chrome: "hover", gumball: "hover", tooltips: "none" };

/** @emoji 🚗 The built-in drivers shipped with the shell. */
export function builtinUiDrivers(): readonly UiDriver[] {
  return [DEFAULT_UI_DRIVER, COMPACT_UI_DRIVER];
}

function requireUiDriverAxis<T extends string>(value: unknown, path: string, allowed: readonly T[]): T {
  if (typeof value === "string" && (allowed as readonly string[]).includes(value)) return value as T;
  throw new Error(`driver.${path} must be one of ${allowed.join(", ")}`);
}

/** @emoji 🔎 Strictly parses and validates a `UiDriver` (unknown axis values throw). */
export function parseUiDriver(json: unknown): UiDriver {
  if (typeof json !== "object" || json === null) throw new Error("driver must be an object");
  const obj = json as Record<string, unknown>;
  if (typeof obj.id !== "string") throw new Error("driver.id must be a string");
  if (typeof obj.label !== "string") throw new Error("driver.label must be a string");
  return {
    id: obj.id,
    label: obj.label,
    labels: requireUiDriverAxis(obj.labels, "labels", ["full", "icons"] as const),
    labelTier: requireUiDriverAxis(obj.labelTier, "labelTier", ["beginner", "normal"] as const),
    drag: requireUiDriverAxis(obj.drag, "drag", ["handle", "surface"] as const),
    chrome: requireUiDriverAxis(obj.chrome, "chrome", ["always", "hover"] as const),
    gumball: requireUiDriverAxis(obj.gumball, "gumball", ["always", "hover"] as const),
    tooltips: requireUiDriverAxis(obj.tooltips, "tooltips", ["full", "minimal", "none"] as const),
  };
}

/** @emoji 💾 Serializes a `UiDriver` to canonical JSON. */
export function serializeUiDriver(driver: UiDriver): string {
  return JSON.stringify(driver, null, 2);
}

/** @emoji 🚗 Resolves a driver id against custom drivers, falling back to a builtin, then {@link DEFAULT_UI_DRIVER}. */
export function resolveUiDriver(id: string, custom: Record<string, UiDriver>): UiDriver {
  if (custom[id]) return custom[id];
  const builtin = builtinUiDrivers().find((driver) => driver.id === id);
  return builtin ?? DEFAULT_UI_DRIVER;
}
// #endregion 🚗UiDriver

// #region 🌈SurfaceChrome
/** @emoji 🌈 Document-level UI chrome shared by Elements shells: appearance (system/light/dark), device (desktop/tablet/mobile), and driver — mirrors sketchpad `Appearance` / `Device` behavior on `documentElement`. */
export type ElementsSurfaceAppearance = "system" | "light" | "dark";
export type ElementsSurfaceDevice = "desktop" | "tablet" | "mobile";

/** @emoji 📱 Shared viewport breakpoint below which shells switch to the automatic mobile device. */
export const UI_MOBILE_MEDIA_QUERY = "(max-width: 767px)";

export interface ElementsSurfaceChromeInput {
  appearance: ElementsSurfaceAppearance;
  device: ElementsSurfaceDevice;
  driver: UiDriver;
}

function applyDocumentBodyBaseColors(): void {
  if (typeof document === "undefined") return;
  document.body.style.backgroundColor = "var(--base)";
  document.body.style.color = "var(--foreground)";
}

/** @emoji 🌓 Resolves whether {@link ElementsSurfaceAppearance} is dark for the current system preference. */
export function resolveElementsSurfaceChromeDark(appearance: ElementsSurfaceAppearance): boolean {
  if (appearance === "dark") return true;
  if (appearance === "light") return false;
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-color-scheme: dark)").matches;
}

/** @emoji 🌓 True when `document.documentElement` currently carries the dark surface chrome class. */
export function isElementsSurfaceChromeDarkApplied(): boolean {
  if (typeof document === "undefined") return false;
  return document.documentElement.classList.contains("dark");
}

type ElementsSurfaceChromeLease = { readonly id: number; readonly input: ElementsSurfaceChromeInput };

let elementsSurfaceChromeLeaseSeq = 0;
const elementsSurfaceChromeLeases: ElementsSurfaceChromeLease[] = [];
let elementsSurfaceChromeDomBindings: ReturnType<typeof createDOMEventBinding> | null = null;
let elementsSurfaceChromeSystemListenersInstalled = false;
let elementsSurfaceChromeDeferredClearFrame = 0;

function activeElementsSurfaceChromeInput(): ElementsSurfaceChromeInput | undefined {
  return elementsSurfaceChromeLeases[elementsSurfaceChromeLeases.length - 1]?.input;
}

function syncElementsSurfaceChromeProviders(input: ElementsSurfaceChromeInput | undefined): void {
  if (input) {
    setUiDriverProvider(() => input.driver);
    return;
  }
  setUiDriverProvider(() => readStoredUiDriver());
}

function applyElementsSurfaceChromeDriverDom(root: HTMLElement, driver: UiDriver): void {
  root.dataset.uiDriver = driver.id;
  root.dataset.uiLabels = driver.labels;
  root.dataset.uiDrag = driver.drag;
  root.dataset.uiChromeReveal = driver.chrome;
  root.dataset.uiGumballReveal = driver.gumball;
  root.dataset.uiTooltips = driver.tooltips;
  syncUiChromeRevealController(driver.chrome);
}

function clearElementsSurfaceChromeDriverDom(root: HTMLElement): void {
  delete root.dataset.uiDriver;
  delete root.dataset.uiLabels;
  delete root.dataset.uiDrag;
  delete root.dataset.uiChromeReveal;
  delete root.dataset.uiGumballReveal;
  delete root.dataset.uiTooltips;
  teardownUiChromeRevealController();
}

// #region 🫥ChromeReveal
/** @emoji 🫥 Extra radius (px) around a reveal region's own rect that still counts as "inside" — makes the invisible-until-hovered bar reachable. */
const CHROME_REVEAL_ACTIVATION_BAND_PX = 24;
/** @emoji 🫥 Screen-edge band (px) that reveals a region anchored to that edge (navbar top, footer bottom), even before the cursor reaches the region's own rect. */
const CHROME_REVEAL_EDGE_BAND_PX = 8;

let chromeRevealBindings: ReturnType<typeof createDOMEventBinding> | null = null;
let chromeRevealFrame = 0;
let chromeRevealLastPoint: { x: number; y: number } | null = null;

function chromeRevealStackAncestor(region: HTMLElement): HTMLElement | null {
  return region.closest<HTMLElement>('[data-slot="window-chrome-stack"], [data-slot="mode-dock-stack"]');
}

function chromeRevealRegionRevealed(region: HTMLElement, x: number, y: number): boolean {
  const rect = region.getBoundingClientRect();
  if (x >= rect.left - CHROME_REVEAL_ACTIVATION_BAND_PX && x <= rect.right + CHROME_REVEAL_ACTIVATION_BAND_PX && y >= rect.top - CHROME_REVEAL_ACTIVATION_BAND_PX && y <= rect.bottom + CHROME_REVEAL_ACTIVATION_BAND_PX) {
    return true;
  }
  const regionName = region.dataset.uiRevealRegion;
  if (regionName === "navbar" && y <= CHROME_REVEAL_EDGE_BAND_PX) return true;
  if (regionName === "footer" && typeof window !== "undefined" && y >= window.innerHeight - CHROME_REVEAL_EDGE_BAND_PX) return true;
  if (regionName === "window-cap") {
    const stack = chromeRevealStackAncestor(region);
    if (stack) {
      const stackRect = stack.getBoundingClientRect();
      if (x >= stackRect.left && x <= stackRect.right && y >= stackRect.top && y <= stackRect.top + CHROME_REVEAL_EDGE_BAND_PX) return true;
    }
  }
  return false;
}

function applyChromeRevealAtPoint(x: number, y: number): void {
  if (typeof document === "undefined") return;
  document.querySelectorAll<HTMLElement>("[data-ui-reveal-region]").forEach((region) => {
    if (chromeRevealRegionRevealed(region, x, y)) region.dataset.uiRevealed = "true";
    else delete region.dataset.uiRevealed;
  });
}

function scheduleChromeRevealUpdate(): void {
  if (chromeRevealFrame !== 0 || typeof requestAnimationFrame === "undefined") return;
  chromeRevealFrame = requestAnimationFrame(() => {
    chromeRevealFrame = 0;
    if (chromeRevealLastPoint) applyChromeRevealAtPoint(chromeRevealLastPoint.x, chromeRevealLastPoint.y);
  });
}

function ensureUiChromeRevealController(): void {
  if (chromeRevealBindings || typeof window === "undefined" || typeof document === "undefined") return;
  const bindings = createDOMEventBinding();
  bindings.listen(window, "pointermove", (event: PointerEvent) => {
    chromeRevealLastPoint = { x: event.clientX, y: event.clientY };
    scheduleChromeRevealUpdate();
  });
  bindings.listen(document, "focusin", (event: FocusEvent) => {
    const region = (event.target as HTMLElement | null)?.closest<HTMLElement>("[data-ui-reveal-region]");
    if (region) region.dataset.uiRevealed = "true";
  });
  bindings.listen(document, "focusout", (event: FocusEvent) => {
    const region = (event.target as HTMLElement | null)?.closest<HTMLElement>("[data-ui-reveal-region]");
    const related = event.relatedTarget as Node | null;
    if (region && (!related || !region.contains(related))) delete region.dataset.uiRevealed;
  });
  chromeRevealBindings = bindings;
}

function teardownUiChromeRevealController(): void {
  chromeRevealBindings?.dispose();
  chromeRevealBindings = null;
  if (typeof cancelAnimationFrame !== "undefined" && chromeRevealFrame !== 0) {
    cancelAnimationFrame(chromeRevealFrame);
  }
  chromeRevealFrame = 0;
  chromeRevealLastPoint = null;
  if (typeof document === "undefined") return;
  document.querySelectorAll<HTMLElement>("[data-ui-reveal-region][data-ui-revealed]").forEach((region) => delete region.dataset.uiRevealed);
}

/** @emoji 🫥 Ensures the pointer/focus reveal tracker is installed iff the driver wants hover-reveal chrome; called whenever driver DOM attrs are (re)applied. */
function syncUiChromeRevealController(chrome: UiDriverReveal): void {
  if (chrome === "hover") ensureUiChromeRevealController();
  else teardownUiChromeRevealController();
}
// #endregion 🫥ChromeReveal

function clearElementsSurfaceChromeDom(): void {
  if (typeof document === "undefined") return;
  const root = document.documentElement;
  root.classList.remove("dark");
  root.classList.remove("touch");
  delete root.dataset.uiDevice;
  clearElementsSurfaceChromeDriverDom(root);
  delete root.dataset.uiAppearance;
  root.style.colorScheme = "";
  document.body.style.backgroundColor = "";
  document.body.style.color = "";
  document.body.style.colorScheme = "";
}

function applyElementsSurfaceChromeAppearanceDom(appearance: ElementsSurfaceAppearance): void {
  if (typeof document === "undefined") return;
  const root = document.documentElement;
  const dark = resolveElementsSurfaceChromeDark(appearance);
  root.classList.toggle("dark", dark);
  root.dataset.uiAppearance = dark ? "dark" : "light";
  const scheme = dark ? "dark" : "light";
  root.style.colorScheme = scheme;
  if (document.body) {
    document.body.style.colorScheme = scheme;
    applyDocumentBodyBaseColors();
  }
}

/** @emoji 🌓 Applies `html.dark` and `color-scheme` before React/CSS load (play/static entries); does not register a surface-chrome lease. */
export function bootstrapElementsSurfaceChromeDocument(appearance: ElementsSurfaceAppearance = "system"): void {
  if (typeof document === "undefined") return;
  cancelElementsSurfaceChromeDeferredClear();
  applyElementsSurfaceChromeAppearanceDom(appearance);
}

function cancelElementsSurfaceChromeDeferredClear(): void {
  if (elementsSurfaceChromeDeferredClearFrame === 0 || typeof cancelAnimationFrame === "undefined") {
    elementsSurfaceChromeDeferredClearFrame = 0;
    return;
  }
  cancelAnimationFrame(elementsSurfaceChromeDeferredClearFrame);
  elementsSurfaceChromeDeferredClearFrame = 0;
}

function scheduleElementsSurfaceChromeDeferredClear(): void {
  if (typeof requestAnimationFrame === "undefined") {
    if (elementsSurfaceChromeLeases.length === 0) {
      clearElementsSurfaceChromeDom();
    }
    return;
  }
  cancelElementsSurfaceChromeDeferredClear();
  elementsSurfaceChromeDeferredClearFrame = requestAnimationFrame(() => {
    elementsSurfaceChromeDeferredClearFrame = 0;
    if (elementsSurfaceChromeLeases.length === 0) {
      clearElementsSurfaceChromeDom();
    }
  });
}

function applyElementsSurfaceChromeDom(input: ElementsSurfaceChromeInput): void {
  if (typeof document === "undefined") return;
  cancelElementsSurfaceChromeDeferredClear();
  applyElementsSurfaceChromeAppearanceDom(input.appearance);
  const root = document.documentElement;
  root.dataset.uiDevice = input.device;
  root.classList.toggle("touch", input.device !== "desktop");
  applyElementsSurfaceChromeDriverDom(root, input.driver);
}

function syncElementsSurfaceChromeDomFromLeaseStack(): void {
  const input = activeElementsSurfaceChromeInput();
  if (!input) {
    clearElementsSurfaceChromeDom();
    return;
  }
  applyElementsSurfaceChromeDom(input);
}

function ensureElementsSurfaceChromeSystemListeners(): void {
  if (elementsSurfaceChromeSystemListenersInstalled || typeof window === "undefined" || typeof document === "undefined") {
    return;
  }
  elementsSurfaceChromeSystemListenersInstalled = true;
  const bindings = createDOMEventBinding();
  if (typeof window.matchMedia !== "function") {
    installElementsSurfaceBrowserDefaultSuppression(bindings);
    elementsSurfaceChromeDomBindings = bindings;
    return;
  }
  const mq = window.matchMedia("(prefers-color-scheme: dark)");
  const onSystemAppearanceChange = (event: MediaQueryListEvent): void => {
    const input = activeElementsSurfaceChromeInput();
    if (!input || input.appearance !== "system") return;
    const root = document.documentElement;
    const dark = event.matches;
    root.classList.toggle("dark", dark);
    root.dataset.uiAppearance = dark ? "dark" : "light";
    const scheme = dark ? "dark" : "light";
    root.style.colorScheme = scheme;
    if (document.body) {
      document.body.style.colorScheme = scheme;
      applyDocumentBodyBaseColors();
    }
    root.dataset.uiDevice = input.device;
    root.classList.toggle("touch", input.device !== "desktop");
    applyElementsSurfaceChromeDriverDom(root, input.driver);
  };
  bindings.listen(mq, "change", onSystemAppearanceChange);
  installElementsSurfaceBrowserDefaultSuppression(bindings);
  elementsSurfaceChromeDomBindings = bindings;
}

/**
 * @emoji 🌈 Imperative surface chrome controller for class-based shells; returns a cleanup that reverts DOM state, browser default input, and the active driver.
 */
export function applyElementsSurfaceChrome(input: ElementsSurfaceChromeInput): () => void {
  const lease: ElementsSurfaceChromeLease = { id: ++elementsSurfaceChromeLeaseSeq, input };
  elementsSurfaceChromeLeases.push(lease);
  ensureElementsSurfaceChromeSystemListeners();
  syncElementsSurfaceChromeProviders(input);
  syncElementsSurfaceChromeDomFromLeaseStack();
  return () => {
    const index = elementsSurfaceChromeLeases.findIndex((entry) => entry.id === lease.id);
    if (index >= 0) {
      elementsSurfaceChromeLeases.splice(index, 1);
    }
    if (elementsSurfaceChromeLeases.length === 0) {
      syncElementsSurfaceChromeProviders(undefined);
      scheduleElementsSurfaceChromeDeferredClear();
      return;
    }
    syncElementsSurfaceChromeProviders(activeElementsSurfaceChromeInput());
    syncElementsSurfaceChromeDomFromLeaseStack();
  };
}

/**
 * @emoji 🌓 Syncs `document.documentElement` (`dark`, `touch`, `data-ui-device`, `data-ui-driver` + axis attrs), body base colors, and {@link setUiDriverProvider}; returns `mobile` for {@link AppProps.mobile}.
 */
export function useElementsSurfaceChrome({ appearance, device, driver }: ElementsSurfaceChromeInput): { mobile: boolean } {
  reactHostPort.useLayoutEffect(() => applyElementsSurfaceChrome({ appearance, device, driver }), [appearance, device, driver]);

  return { mobile: device === "mobile" };
}

/**
 * @emoji 🌓 Observes document appearance attributes and runs `sync` on mount and whenever the root appearance changes.
 * Holds `sync` in a ref so callers can pass an inline arrow without retriggering the effect every render
 * (React 19: unstable `sync` identity → effect → `paintOverlays`/`setState` → re-render → Maximum update depth).
 */
export function useCanvasAppearanceSync(sync: () => void, enabled = true): void {
  const syncRef = reactHostPort.useRef(sync);
  syncRef.current = sync;
  reactHostPort.useEffect(() => {
    if (!enabled || typeof document === "undefined" || typeof MutationObserver === "undefined") return;
    const run = () => syncRef.current();
    run();
    const root = document.documentElement;
    const observer = new MutationObserver(run);
    observer.observe(root, { attributes: true, attributeFilter: ["class", "style", "data-ui-appearance", "data-ui-theme"] });
    return () => observer.disconnect();
  }, [enabled]);
}

/** @emoji 🧪 Clears surface-chrome leases and DOM overrides between vitest cases. */
export function resetElementsSurfaceChromeForTests(): void {
  cancelElementsSurfaceChromeDeferredClear();
  elementsSurfaceChromeLeases.length = 0;
  syncElementsSurfaceChromeProviders(undefined);
  clearElementsSurfaceChromeDom();
}

// #region 🎛️UiChromePrefs
/** @emoji 🚗 localStorage key for the active driver id (builtin or `custom.<slug>`). */
export const UI_CHROME_DRIVER_STORAGE_KEY = "ui.chrome.driver";

/** @emoji 🚗 Reads the persisted active driver id from localStorage, defaulting to `"default"`. */
export function readStoredUiDriverId(): string {
  if (typeof localStorage === "undefined") return DEFAULT_UI_DRIVER.id;
  return localStorage.getItem(UI_CHROME_DRIVER_STORAGE_KEY) || DEFAULT_UI_DRIVER.id;
}

/** @emoji 🚗 Persists the active driver id to localStorage. */
export function writeStoredUiDriverId(id: string): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(UI_CHROME_DRIVER_STORAGE_KEY, id);
}

/** @emoji 🚗 localStorage key for the user's saved custom drivers, keyed by driver id. */
export const UI_CUSTOM_DRIVERS_STORAGE_KEY = "ui.drivers.custom";

/** @emoji 🚗 Reads the user's saved custom drivers from localStorage; discards any entry that fails to parse. */
export function readStoredUiCustomDrivers(): Record<string, UiDriver> {
  if (typeof localStorage === "undefined") return {};
  const raw = localStorage.getItem(UI_CUSTOM_DRIVERS_STORAGE_KEY);
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const out: Record<string, UiDriver> = {};
    for (const [id, value] of Object.entries(parsed)) {
      try {
        out[id] = parseUiDriver(value);
      } catch {
        /* drop invalid saved driver */
      }
    }
    return out;
  } catch {
    return {};
  }
}

/** @emoji 🚗 Persists the user's saved custom drivers to localStorage. */
export function writeStoredUiCustomDrivers(drivers: Record<string, UiDriver>): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(UI_CUSTOM_DRIVERS_STORAGE_KEY, JSON.stringify(drivers));
}

/** @emoji 🚗 Resolves the active driver from localStorage (non-React fallback for non-hook consumers). */
export function readStoredUiDriver(): UiDriver {
  return resolveUiDriver(readStoredUiDriverId(), readStoredUiCustomDrivers());
}

/** @emoji 🌓 localStorage key for surface appearance (system/light/dark). */
export const UI_CHROME_APPEARANCE_STORAGE_KEY = "ui.chrome.appearance";

/** @emoji 🌓 Reads persisted surface appearance from localStorage. */
export function readStoredUiChromeAppearance(): ElementsSurfaceAppearance {
  if (typeof localStorage === "undefined") return "system";
  const raw = localStorage.getItem(UI_CHROME_APPEARANCE_STORAGE_KEY);
  if (raw === "light" || raw === "dark" || raw === "system") return raw;
  return "system";
}

/** @emoji 🌓 Persists surface appearance to localStorage. */
export function writeStoredUiChromeAppearance(appearance: ElementsSurfaceAppearance): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(UI_CHROME_APPEARANCE_STORAGE_KEY, appearance);
}

/** @emoji 📐 User-selectable layout device; mobile is automatic and excluded here. */
export type UiChromeLayout = "desktop" | "tablet";

/** @emoji 📐 localStorage key for the user-selected desktop/tablet layout. */
export const UI_CHROME_LAYOUT_STORAGE_KEY = "ui.chrome.layout";

/** @emoji 📐 Reads the persisted layout preference from localStorage, defaulting to desktop. */
export function readStoredUiChromeLayout(): UiChromeLayout {
  if (typeof localStorage === "undefined") return "desktop";
  return localStorage.getItem(UI_CHROME_LAYOUT_STORAGE_KEY) === "tablet" ? "tablet" : "desktop";
}

/** @emoji 📐 Persists the layout preference to localStorage. */
export function writeStoredUiChromeLayout(layout: UiChromeLayout): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(UI_CHROME_LAYOUT_STORAGE_KEY, layout);
}

/** @emoji 🌐 localStorage key for the active UI locale. */
export const UI_CHROME_LOCALE_STORAGE_KEY = "ui.chrome.locale";

/** @emoji 🌐 Reads the persisted UI locale from localStorage, if any. */
export function readStoredUiChromeLocale(): UiLocale | null {
  if (typeof localStorage === "undefined") return null;
  const raw = localStorage.getItem(UI_CHROME_LOCALE_STORAGE_KEY);
  return raw === "en" || raw === "de" ? raw : null;
}

/** @emoji 🌐 Persists the active UI locale to localStorage. */
export function writeStoredUiChromeLocale(locale: UiLocale): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(UI_CHROME_LOCALE_STORAGE_KEY, locale);
}

/** @emoji 🗣️ Id of the always-available default terminology (no term substitutions). */
export const UI_TERMINOLOGY_NATIVE = "native";

/** @emoji 🗣️ localStorage key for the active app terminology id. */
export const UI_CHROME_TERMINOLOGY_STORAGE_KEY = "ui.chrome.terminology";

/** @emoji 🗣️ Reads the persisted terminology id from localStorage, defaulting to native. */
export function readStoredUiChromeTerminology(): string {
  if (typeof localStorage === "undefined") return UI_TERMINOLOGY_NATIVE;
  return localStorage.getItem(UI_CHROME_TERMINOLOGY_STORAGE_KEY) || UI_TERMINOLOGY_NATIVE;
}

/** @emoji 🗣️ Persists the active terminology id to localStorage. */
export function writeStoredUiChromeTerminology(id: string): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(UI_CHROME_TERMINOLOGY_STORAGE_KEY, id);
}

/** @emoji 🎨 localStorage key for the active theme id (builtin or `custom.<slug>`). */
export const UI_CHROME_THEME_ID_STORAGE_KEY = "ui.chrome.theme";

/** @emoji 🎨 Reads the persisted active theme id from localStorage, if any. */
export function readStoredUiChromeThemeId(): string | null {
  if (typeof localStorage === "undefined") return null;
  return localStorage.getItem(UI_CHROME_THEME_ID_STORAGE_KEY);
}

/** @emoji 🎨 Persists the active theme id to localStorage. */
export function writeStoredUiChromeThemeId(id: string): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(UI_CHROME_THEME_ID_STORAGE_KEY, id);
}

/** @emoji 🎨 localStorage key for a full snapshot of the active theme (boot-time fallback before builtin/custom lookup resolves). */
export const UI_CHROME_THEME_SNAPSHOT_STORAGE_KEY = "ui.chrome.theme.snapshot";

/** @emoji 🎨 Reads the persisted active theme snapshot from localStorage; discards it silently if invalid. */
export function readStoredUiChromeThemeSnapshot(): UiTheme | null {
  if (typeof localStorage === "undefined") return null;
  const raw = localStorage.getItem(UI_CHROME_THEME_SNAPSHOT_STORAGE_KEY);
  if (!raw) return null;
  try {
    return parseUiTheme(JSON.parse(raw));
  } catch {
    return null;
  }
}

/** @emoji 🎨 Persists a full snapshot of the active theme to localStorage. */
export function writeStoredUiChromeThemeSnapshot(theme: UiTheme): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(UI_CHROME_THEME_SNAPSHOT_STORAGE_KEY, serializeUiTheme(theme));
}

/** @emoji 🎨 localStorage key for the user's saved custom themes, keyed by theme id. */
export const UI_CUSTOM_THEMES_STORAGE_KEY = "ui.themes.custom";

/** @emoji 🎨 Reads the user's saved custom themes from localStorage; discards any entry that fails to parse. */
export function readStoredUiCustomThemes(): Record<string, UiTheme> {
  if (typeof localStorage === "undefined") return {};
  const raw = localStorage.getItem(UI_CUSTOM_THEMES_STORAGE_KEY);
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const out: Record<string, UiTheme> = {};
    for (const [id, value] of Object.entries(parsed)) {
      try {
        out[id] = parseUiTheme(value);
      } catch {
        /* drop invalid saved theme */
      }
    }
    return out;
  } catch {
    return {};
  }
}

/** @emoji 🎨 Persists the user's saved custom themes to localStorage. */
export function writeStoredUiCustomThemes(themes: Record<string, UiTheme>): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(UI_CUSTOM_THEMES_STORAGE_KEY, JSON.stringify(themes));
}

/** @emoji 🧵 localStorage key for WASM compute worker thread count. */
export const UI_COMPUTE_WORKER_COUNT_STORAGE_KEY = "ui.compute.workerCount";

/** @emoji 🧵 Default compute workers: `navigator.hardwareConcurrency` or 1. */
export function defaultComputeWorkerCount(): number {
  if (typeof navigator !== "undefined" && typeof navigator.hardwareConcurrency === "number" && navigator.hardwareConcurrency > 0) {
    return navigator.hardwareConcurrency;
  }
  return 1;
}

/** @emoji 🧵 Reads persisted compute worker count from localStorage. */
export function readStoredComputeWorkerCount(): number {
  if (typeof localStorage === "undefined") return defaultComputeWorkerCount();
  const raw = localStorage.getItem(UI_COMPUTE_WORKER_COUNT_STORAGE_KEY);
  if (raw == null || raw === "") return defaultComputeWorkerCount();
  const parsed = Number.parseInt(raw, 10);
  if (!Number.isFinite(parsed) || parsed < 1) return defaultComputeWorkerCount();
  return parsed;
}

/** @emoji 🧵 Persists compute worker count to localStorage. */
export function writeStoredComputeWorkerCount(count: number): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(UI_COMPUTE_WORKER_COUNT_STORAGE_KEY, String(Math.max(1, Math.floor(count))));
}

/** @emoji 🧵 True when SharedArrayBuffer thread pools are available. */
export function isCrossOriginIsolatedRuntime(): boolean {
  return typeof crossOriginIsolated !== "undefined" && crossOriginIsolated === true;
}

/** @emoji 🧵 Effective worker count after cross-origin isolation fallback. */
export function effectiveComputeWorkerCount(requested = readStoredComputeWorkerCount()): number {
  if (!isCrossOriginIsolatedRuntime()) return 1;
  return Math.max(1, Math.floor(requested));
}

/** @emoji 🎓 localStorage key prefix for whether an app's introduction has already been shown on this device. */
export const UI_INTRODUCTION_SEEN_STORAGE_KEY_PREFIX = "ui.introduction.seen.";

/** @emoji 🎓 Reads whether `appId`'s introduction has already been shown — auto-start checks this once
 * per app; replaying stays available via the `startIntroduction` action regardless of this flag. */
export function readStoredIntroductionSeen(appId: string): boolean {
  if (typeof localStorage === "undefined") return false;
  return localStorage.getItem(`${UI_INTRODUCTION_SEEN_STORAGE_KEY_PREFIX}${appId}`) === "true";
}

/** @emoji 🎓 Marks `appId`'s introduction as shown so it stops auto-starting on future launches. */
export function writeStoredIntroductionSeen(appId: string): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(`${UI_INTRODUCTION_SEEN_STORAGE_KEY_PREFIX}${appId}`, "true");
}

const UiDriverContext = reactHostPort.createContext<UiDriver | null>(null);

let _uiDriverProvider: (() => UiDriver) | null = null;

/** @emoji 🚗 Registers the active driver resolver for non-React consumers (e.g. {@link resolveTranslationLabel}). */
export function setUiDriverProvider(fn: () => UiDriver): void {
  _uiDriverProvider = fn;
}

/** @emoji 🚗 Resolves the active driver outside React render context. */
export function activeUiDriver(): UiDriver {
  return _uiDriverProvider ? _uiDriverProvider() : readStoredUiDriver();
}

/** @emoji 🚗 The active driver controlling labels, drag affordances, chrome/gumball reveal, and tooltips. */
export function useUiDriver(): UiDriver {
  const contextValue = reactHostPort.useContext(UiDriverContext);
  if (contextValue !== null) return contextValue;
  return activeUiDriver();
}

/** @emoji 🚗 Supplies driver state to a subtree, overriding the ambient/stored driver. */
export function UiDriverProvider({ driver, children }: { readonly driver: UiDriver; readonly children: React.ReactNode }): React.ReactElement {
  reactHostPort.useEffect(() => {
    setUiDriverProvider(() => driver);
    return () => setUiDriverProvider(() => readStoredUiDriver());
  }, [driver]);
  return <UiDriverContext.Provider value={driver}>{children}</UiDriverContext.Provider>;
}

/** @emoji 🫳 True when the driver wants whole-surface dragging (no dedicated grip handle). */
export function useUiDriverDragSurface(): boolean {
  return useUiDriver().drag === "surface";
}

/** @emoji 🎙️ The active driver's tooltip richness. */
export function useUiDriverTooltips(): UiDriverTooltips {
  return useUiDriver().tooltips;
}

let _controlLabelIdResolver: (id: string) => string = (id) => id;

/** @emoji 🏷️ Registers a product-specific mapper from shell control ids (`ui.*`) to i18n keys. */
export function setControlLabelIdResolver(resolver: (id: string) => string): void {
  _controlLabelIdResolver = resolver;
}

/** @emoji 🏷️ Maps shell control ids to i18n keys for inline labels (identity until a product resolver is set). */
export function resolveControlLabelId(id: string): string {
  if (id.startsWith("ui.nav.")) {
    const segment = id.slice("ui.nav.".length);
    if (segment === "back" || segment === "forward" || segment === "up") {
      return _controlLabelIdResolver(`ui.nav.${segment}`);
    }
  }
  if (id === "ui.search.toggle") {
    return _controlLabelIdResolver("ui.search.toggle");
  }
  if (id === "ui.find.toggle") {
    return _controlLabelIdResolver("ui.find.toggle");
  }
  if (id === "ui.fullscreen.toggle") {
    return _controlLabelIdResolver("ui.fullscreen.toggle");
  }
  if (id === "ui.mobilePanel.toggle") {
    return _controlLabelIdResolver("ui.mobilePanel.toggle");
  }
  if (id.startsWith("ui.panelToggle.")) {
    return _controlLabelIdResolver(`ui.panelToggle.${id.slice("ui.panelToggle.".length)}`);
  }
  if (id.startsWith("ui.ribbon.group.")) {
    return _controlLabelIdResolver(`ui.ribbon.parent.${id.slice("ui.ribbon.group.".length)}`);
  }
  if (id.startsWith("ui.ribbon.") && id.includes(".group.")) {
    return _controlLabelIdResolver(`ui.ribbon.parent.${id.slice(id.lastIndexOf(".group.") + ".group.".length)}`);
  }
  if (id === "ui.windowSearch.suggestions") {
    return _controlLabelIdResolver("ui.windowSearch.suggestions");
  }
  if (id === "ui.engagement.actions") {
    return _controlLabelIdResolver("ui.engagement.actions");
  }
  if (id === "search-input" || id === "ui.windowSearch.action") {
    return _controlLabelIdResolver("ui.windowSearch.action");
  }
  if (id.startsWith("playground.panel.")) {
    return _controlLabelIdResolver(`ui.panelToggle.${id.slice("playground.panel.".length)}`);
  }
  return _controlLabelIdResolver(id);
}

/** @emoji 🏷️ Panel kind slug from a panel-toggle control id (`ui.panelToggle.*`, `playground.panel.*`, sketchpad navbar keys). */
export function panelKindFromPanelToggleControlId(id: string): string | undefined {
  if (id.startsWith("ui.panelToggle.")) return id.slice("ui.panelToggle.".length);
  if (id.startsWith("playground.panel.")) return id.slice("playground.panel.".length);
  if (id.startsWith("compose.sketchpad.navbar.panelToggle.")) return id.slice("compose.sketchpad.navbar.panelToggle.".length);
  return undefined;
}

/** @emoji 🏷️ True for internal engagement/search chrome element ids that must not surface as humanized tooltips. */
export function isInternalChromeControlId(id: string | undefined | null): boolean {
  if (!id) return false;
  return id.startsWith("engagement-") || id.startsWith("engagement.") || id.startsWith("search-") || id.startsWith("search.");
}

/** @emoji 🔤 Turns a control id segment into a short title (e.g. `panelToggle` → `Panel Toggle`). */
export function humanizeControlSegment(segment: string): string {
  const normalized = segment
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/[._-]+/g, " ")
    .trim();
  if (!normalized) return segment;
  return normalized.replace(/\b\w/g, (char) => char.toUpperCase());
}

/** @emoji 🔤 Human-readable caption from the last segment of a dotted control id. */
export function humanizeControlId(id: string): string {
  const segment = id.split(".").filter(Boolean).pop() ?? id;
  return humanizeControlSegment(segment);
}

/** @emoji 🏷️ Resolves the user-facing caption for a control (i18n, explicit text, or `ui.*` fallback). */
export function useControlAccessibleLabel(id: string | undefined, text?: string): string | undefined {
  if (text !== undefined && text !== "") return text;
  if (!id || isInternalChromeControlId(id)) return undefined;
  const labelId = resolveControlLabelId(id);
  const localized = useIdLabel(labelId);
  if (localized) return localized;
  const panelKind = panelKindFromPanelToggleControlId(id);
  if (panelKind) {
    const fromUiPanel = useIdLabel(`ui.panelToggle.${panelKind}`);
    if (fromUiPanel) return fromUiPanel;
    return humanizeEngagementStepId(panelKind);
  }
  if (labelId.startsWith("ui.")) return humanizeControlId(labelId);
  return undefined;
}

/** @emoji 🏷️ Resolves inline icon+label caption for buttons/toggles; omitted when the driver hides labels. */
export function useControlInlineText(id: string | undefined, text?: string): string | undefined {
  const driver = useUiDriver();
  const accessibleLabel = useControlAccessibleLabel(id, text);
  return driver.labels === "icons" ? undefined : accessibleLabel;
}

/** @emoji 🏷️ Native title/aria-label for chrome controls (avoids Radix tooltip `setTrigger` ref update loops). */
export function ChromeControlHint({ id, text, children }: { readonly id?: string; readonly text?: string; readonly children: React.ReactElement }): React.ReactElement {
  const label = useControlAccessibleLabel(id, text);
  if (!label || !React.isValidElement(children)) return children;
  const childProps = children.props as { readonly title?: string; readonly "aria-label"?: string };
  return React.cloneElement(children, {
    title: childProps.title ?? label,
    "aria-label": childProps["aria-label"] ?? label,
  } as Record<string, unknown>);
}
// #endregion 🎛️UiChromeCompact

// #endregion 🌈SurfaceChrome

// #region 🪁I18n Resources

// Domain-neutral UI translation bundles (settings, tooltip, generic shell `ui.*` ids).
// Product-specific bundles (e.g. compose sketchpad) register via {@link registerUiTranslationBundles}.

// #region 🔑Schema & Keys
// Type/key-derivation machinery: locale codes, label shapes, the deep dot-path key type, and compile-time key-coverage checks.

/** @emoji 🪁 Supported UI locale codes — the single source is `@semio-tech/framework-core`'s
 * `ShellLocale`, so a brand's `locks.locale` and this chrome bundle's coverage can never drift apart. */
export type UiLocale = ShellLocale;

/** @emoji 🪁 Label pair resolved by the active driver's `labelTier` axis. */
export type UiLabelPair = { readonly normal: string; readonly beginner: string };

/** @emoji 🪁 Translation leaf with optional manual, tutorial, and hotkey metadata. */
export type UiLabelValue = {
  readonly label: UiLabelPair;
  readonly manual?: string;
  readonly tutorial?: string;
  readonly hotkey?: string;
};

/** @emoji 🪁 Ribbon collection ids for ribbon collection toggles. */
export type UiRibbonParentCategory =
  | "history"
  | "hand"
  | "selection"
  | "lasso"
  | "filter"
  | "open"
  | "save"
  | "transfer"
  | "transform"
  | "create"
  | "view"
  | "actions"
  | "settings"
  | "methods"
  | "mode"
  | "targets"
  | "export"
  | "tools"
  | "utilities"
  | "sync";

/** @emoji 🪁 i18n key for a ribbon collection toggle. */
export type UiRibbonParentKey = `ui.ribbon.parent.${string}`;

type UiRibbonParentEntries = { readonly [K in UiRibbonParentCategory]: UiLabelValue };

type DeepUiTranslationKeys<T, Prefix extends string = ""> = T extends UiLabelValue
  ? Prefix extends ""
    ? never
    : Prefix
  : T extends string
    ? Prefix extends ""
      ? never
      : Prefix
    : T extends number | boolean | null | undefined
      ? never
      : T extends readonly unknown[]
        ? never
        : {
            [K in keyof T & string]: DeepUiTranslationKeys<T[K], Prefix extends "" ? K : `${Prefix}.${K}`>;
          }[keyof T & string];

