/** @emoji 📑 Panel tab button with icon and mandatory name (no per-tab borders — {@link panelTabBarClass} owns dividers). */
export const panelTabButtonClass = cn(
  "inline-flex min-h-0 shrink-0 items-center gap-tiny border-e border-solid !border-normal last:border-e-0 bg-transparent p-0",
  "cursor-pointer whitespace-nowrap text-xs leading-none text-element transition-colors",
  "outline-none focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-active-base",
  "[&[data-active=true]:not(:first-child)]:border-s [&[data-active=true]:not(:first-child)]:-ms-px",
  hoverExcludingHandleBgFillClass,
  hoverExcludingHandleTextEmphasizedClass,
);

/** @emoji 📑 Floating panel tab strip inside {@link WindowChrome} — hugs tabs; silhouette + per-tab pills own every stroke. */
export function panelAnchorTabBarClass(_direction: "up" | "down"): string {
  return cn(panelTabBarScrollClass, "h-medium");
}

/** @emoji 📑 Panel tab button padding. */
export const panelAnchorTabButtonClass = cn(panelTabButtonClass, "px-tiny");

/** @emoji 📑 Framed root-row strip for a chrome-hosted anchor's tabs (see {@link PanelChromeTabBar}) — frosted panel chrome living inline in the navbar/footer instead of on the floating panel. */
export const panelChromeTabBarClass = cn(panelTabBarBaseClass, "h-medium border rounded-sm", borderNormalClass, glassClass);

//#region 🫳DragAffordance

/**
 * @emoji 🫳 Universal grip that starts a drag — pass `onPointerDown` for pointer-capture drags (and optionally the rest of {@link usePointerDrag}'s handlers), spread dnd-kit `attributes`/`listeners`, or use as a pure affordance on whole-surface draggables.
 * `emphasized` mirrors the ambient active/ready state of the element it belongs to.
 * Parent hover emphasis is CSS: `[data-hover-scope]:hover [data-slot="drag-handle"]` in `ui.css` — the grip paints its own muted color at rest and cannot inherit `hover:text-emphasized` from the label/icon beside it.
 */
export const DragHandle: React.FC<{
  readonly onPointerDown?: React.PointerEventHandler<HTMLSpanElement>;
  readonly onPointerMove?: React.PointerEventHandler<HTMLSpanElement>;
  readonly onPointerUp?: React.PointerEventHandler<HTMLSpanElement>;
  readonly onPointerCancel?: React.PointerEventHandler<HTMLSpanElement>;
  readonly attributes?: object;
  readonly listeners?: Record<string, unknown>;
  readonly onClick?: React.MouseEventHandler<HTMLSpanElement>;
  readonly className?: string;
  readonly emphasized?: boolean;
}> = ({ onPointerDown, onPointerMove, onPointerUp, onPointerCancel, attributes, listeners, onClick, className, emphasized = false }) => (
  <span
    data-slot="drag-handle"
    className={cn("inline-flex shrink-0 cursor-grab touch-none items-center justify-center transition-colors hover:text-emphasized active:cursor-grabbing", emphasized ? "text-emphasized" : "text-muted-foreground", className)}
    onPointerDown={onPointerDown}
    onPointerMove={onPointerMove}
    onPointerUp={onPointerUp}
    onPointerCancel={onPointerCancel}
    onClick={onClick}
    onPointerEnter={(event) => {
      event.currentTarget.closest(`[${HANDLE_HOVER_SCOPE_ATTR}]`)?.setAttribute("data-handle-hovered", "true");
    }}
    onPointerLeave={(event) => {
      event.currentTarget.closest(`[${HANDLE_HOVER_SCOPE_ATTR}]`)?.removeAttribute("data-handle-hovered");
    }}
    {...(attributes as React.ComponentProps<"span">)}
    {...(listeners as React.ComponentProps<"span">)}
  >
    <GripVerticalIcon size={12} />
  </span>
);

/** @emoji 🎯 Passive drop-zone fill — secondary accent, kept visually distinct from the stronger primary-accent indicator on the actively hovered target. */
export const dropZoneReadyFillClass = "bg-[var(--accent-secondary)]";

/** @emoji 🎯 Label/icon emphasis paired with {@link dropZoneReadyFillClass} so text stays legible on the fill. */
export const dropZoneReadyTextClass = "text-emphasized";

/** @emoji 🎯 Combined passive drop-zone treatment for single-container elements (fill + emphasized text/icons) while a compatible drag is in flight — the hovered zone keeps its stronger accent indicator on top of this. Rows that split shell (text) from content (fill) — e.g. {@link TreeItem}, {@link SortableTreeItem}, {@link TreeSection} — apply {@link dropZoneReadyTextClass} and {@link dropZoneReadyFillClass} separately instead, so the fill never bleeds into the guide gutter. */
export const dropZoneReadyClass = cn(dropZoneReadyFillClass, dropZoneReadyTextClass);

//#endregion 🫳DragAffordance

/** @emoji 📑 Shared panel/mobile panel tab bar variant. */
/** @emoji 📑 `"chrome"` hosts the SAME root row (full DnD) inline in the navbar/footer chrome instead of on the floating panel — see {@link PanelChromeTabBar}. */
export type PanelTabBarVariant = "panel" | "mobile" | "chrome";

/** @emoji 🧭 Validates a path's segments against a node tree, truncating at the first segment that no longer exists at its level — no first-sibling substitution, no auto-descend (progressive reveal owns how deep a path goes). `[]` is a valid result. */
export function reconcileActivePath<T extends { readonly id: string }>(nodes: readonly T[], path: readonly string[], childrenOf: (node: T) => readonly T[] | undefined): string[] {
  let current = nodes;
  const reconciled: string[] = [];
  for (const id of path) {
    const node = current.find((candidate) => candidate.id === id);
    if (!node) break;
    reconciled.push(id);
    current = childrenOf(node) ?? [];
  }
  return reconciled;
}

/** @emoji 🧭 Eight anchors a panel or pane can grow from: the display's four corners, plus the four edge middles (top/bottom/left/right) — no center anchor, since floating chrome must never fully occlude the canvas. */
export const ANCHORS = ["top-left", "top-middle", "top-right", "right-middle", "bottom-right", "bottom-middle", "bottom-left", "left-middle"] as const;

/** @emoji 🧭 One of the eight anchors a panel or pane can grow from. */
export type Anchor = (typeof ANCHORS)[number];

/** @emoji 🧭 `"top"`/`"middle"`/`"bottom"` row of an {@link Anchor} — `left-middle`/`right-middle` sit in the middle row. */
export function anchorVertical(anchor: Anchor): "top" | "middle" | "bottom" {
  if (anchor.startsWith("top")) return "top";
  if (anchor.startsWith("bottom")) return "bottom";
  return "middle";
}

/** @emoji 🧭 `"left"`/`"middle"`/`"right"` column of an {@link Anchor} — `top-middle`/`bottom-middle` sit in the middle column. */
export function anchorHorizontal(anchor: Anchor): "left" | "middle" | "right" {
  switch (anchor) {
    case "top-left":
    case "bottom-left":
    case "left-middle":
      return "left";
    case "top-right":
    case "bottom-right":
    case "right-middle":
      return "right";
    default:
      return "middle";
  }
}

// #region 🧭Flow Context
/** @emoji 🧭 Horizontal reading direction — `"rtl"` mirrors icon/label order and rides on native CSS `dir`. */
export type FlowInline = "ltr" | "rtl";

/** @emoji 🧭 Vertical stacking direction — `"up"` grows content toward the display center (see {@link Ribbon}). */
export type FlowBlock = "down" | "up";

/** @emoji 🧭 The flow descendant chrome mirrors against. */
export interface Flow {
  readonly inline: FlowInline;
  readonly block: FlowBlock;
}

const DEFAULT_FLOW: Flow = { inline: "ltr", block: "down" };

const FlowContext = reactHostPort.createContext<Flow>(DEFAULT_FLOW);

/** @emoji 🧭 Sets the flow for descendant chrome, merging partial overrides onto the parent flow (nesting overrides). */
export const FlowProvider: React.FC<{
  readonly inline?: FlowInline;
  readonly block?: FlowBlock;
  readonly children: React.ReactNode;
}> = ({ inline, block, children }) => {
  const parent = reactHostPort.useContext(FlowContext);
  const value = reactHostPort.useMemo((): Flow => ({ inline: inline ?? parent.inline, block: block ?? parent.block }), [inline, block, parent]);
  return <FlowContext.Provider value={value}>{children}</FlowContext.Provider>;
};

/** @emoji 🪝 Returns the nearest {@link FlowProvider} flow (defaults to LTR/down). */
export function useFlow(): Flow {
  return reactHostPort.useContext(FlowContext);
}

/** @emoji 🧭 The mirrored {@link Flow} a {@link Panel} or {@link Pane} grows into — right anchors flip inline, bottom anchors flip block; middle anchors (row or column) never mirror. */
export function flowFromAnchor(anchor: Anchor): Flow {
  return { inline: anchorHorizontal(anchor) === "right" ? "rtl" : "ltr", block: anchorVertical(anchor) === "bottom" ? "up" : "down" };
}

/** @emoji 🧭 Edge insets for an {@link Anchor} plus responsive width/height clamps to its containing region — corners inset on both axes, an edge-middle anchor centers along its middle axis via a translate. Shared by {@link Panel} and {@link Pane} so both float from identical math. */
export function anchorPositionStyle(anchor: Anchor): React.CSSProperties {
  const horizontal = anchorHorizontal(anchor);
  const vertical = anchorVertical(anchor);
  const style: React.CSSProperties = {
    maxWidth: "calc(100% - (var(--spacing-single) * 2))",
    maxHeight: "calc(100% - (var(--spacing-single) * 2))",
  };
  if (horizontal === "middle") {
    style.left = "50%";
    style.transform = "translateX(-50%)";
  } else {
    style[horizontal] = "var(--spacing-single)";
  }
  if (vertical === "middle") {
    style.top = "50%";
    style.transform = style.transform ? `${style.transform} translateY(-50%)` : "translateY(-50%)";
  } else {
    style[vertical] = "var(--spacing-single)";
  }
  return style;
}

/** @emoji 🧭 Chevron {@link IconName} that points toward where a fold's content is — the opposite state's chevron, mirrored for {@link FlowInline} `"rtl"`. `pointsOut` is `true` when the fold is collapsed (chevron points toward the hidden content) and `false` when expanded (chevron points back at the fold). */
export function flowChevronIconName(inline: FlowInline, pointsOut: boolean): IconName {
  const right = inline === "rtl" ? pointsOut : !pointsOut;
  return right ? "chevron-right" : "chevron-left";
}
// #endregion 🧭Flow Context

/** @emoji 🌱 One draggable tree granule inside a leaf tab — dockable between leaf tabs, rendered as its own collapsible section. */
export interface PanelTreeUnit {
  readonly id: string;
  readonly tree: TreePanelSource;
  readonly label?: string;
  readonly icon?: React.ComponentType<{ size?: number }>;
  readonly order?: number;
}

/** @emoji 🍃 Leaf tab — its `trees` are the panel-body units shown when active, each rendered as its own section. */
export interface PanelTabLeaf {
  readonly kind: "leaf";
  readonly id: string;
  readonly icon: React.ComponentType<{ size?: number }>;
  /** @emoji 🏷️ Mandatory tab label shown after the icon. */
  readonly name: string;
  readonly order?: number;
  /** @emoji 🌲 Tree units for this tab — draggable between leaf tabs, rendered as sections. */
  readonly trees: readonly PanelTreeUnit[];
}

/** @emoji 🍃 Builds a {@link PanelTabLeaf} with exactly one tree, wrapped as a single {@link PanelTreeUnit} (unit id: `` `${id}.tree` ``). */
export function singleTreeLeaf(leaf: { readonly id: string; readonly icon: React.ComponentType<{ size?: number }>; readonly name: string; readonly order?: number; readonly tree: TreePanelSource }): PanelTabLeaf {
  return { kind: "leaf", id: leaf.id, icon: leaf.icon, name: leaf.name, order: leaf.order, trees: [{ id: `${leaf.id}.tree`, tree: leaf.tree }] };
}

/** @emoji 🌳 Branch tab — its `children` render as the row below this one when active. */
export interface PanelTabBranch {
  readonly kind: "branch";
  readonly id: string;
  readonly icon: React.ComponentType<{ size?: number }>;
  readonly name: string;
  readonly order?: number;
  readonly children: readonly PanelTabNode[];
}

/** @emoji 🌲 One node in the arbitrarily nestable panel tab tree. */
export type PanelTabNode = PanelTabLeaf | PanelTabBranch;

/** @emoji 🌳 `childrenOf` for {@link reconcileActivePath} over a {@link PanelTabNode} tree. */
export function panelTabChildren(node: PanelTabNode): readonly PanelTabNode[] | undefined {
  return node.kind === "branch" ? node.children : undefined;
}

/** @emoji 🔍 Walks a path from the root, returning the node at its end (or undefined if the path doesn't resolve). */
export function findPanelTabNode(tabs: readonly PanelTabNode[], path: readonly string[]): PanelTabNode | undefined {
  let nodes = tabs;
  let found: PanelTabNode | undefined;
  for (const id of path) {
    found = nodes.find((node) => node.id === id);
    if (!found) return undefined;
    nodes = panelTabChildren(found) ?? [];
  }
  return found;
}

/** @emoji 🔍 Depth-first path from the root to the tab with `id`, or undefined if absent. */
export function findPanelTabPath(tabs: readonly PanelTabNode[], id: string): string[] | undefined {
  for (const node of tabs) {
    if (node.id === id) return [node.id];
    if (node.kind === "branch") {
      const childPath = findPanelTabPath(node.children, id);
      if (childPath) return [node.id, ...childPath];
    }
  }
  return undefined;
}

/** @emoji 🌱 A node's own id plus every descendant's id — the memory entries a collapsed/reset branch must forget. */
function panelTabSubtreeIds(node: PanelTabNode): string[] {
  const children = panelTabChildren(node);
  return children ? [node.id, ...children.flatMap(panelTabSubtreeIds)] : [node.id];
}

/** @emoji 🌱 Result of interpreting one raw tab press: the next active path, the next per-branch drill-down memory, and whether the press should fold the hosting panel instead. */
export interface PanelTabSelectionResult {
  readonly path: readonly string[];
  readonly memory: Readonly<Record<string, string>>;
  readonly fold: boolean;
}

/**
 * 🌱 Interprets a raw tab press for progressive reveal (see {@link PanelTabBar}): re-pressing the already-active
 * segment collapses it; a root re-press always folds the panel without changing its path or remembered state; a fresh pick adopts
 * the pressed path and extends it from `memory` — each branch remembers the last child drilled into, pruning stale
 * entries that no longer match the tree — recording a fresh hop for every step of the resulting path.
 **/
export function progressPanelTabSelection(tabs: readonly PanelTabNode[], currentPath: readonly string[], selectedPath: readonly string[], memory: Readonly<Record<string, string>>): PanelTabSelectionResult {
  const validatedSelected = reconcileActivePath(tabs, selectedPath, panelTabChildren);
  const d = validatedSelected.length - 1;
  if (d < 0) return { path: currentPath, memory, fold: false };
  const pressed = validatedSelected[d];

  const clearSubtreeMemory = (node: PanelTabNode | undefined, fallbackId: string): Readonly<Record<string, string>> => {
    const clearedIds = new Set(node ? panelTabSubtreeIds(node) : [fallbackId]);
    return Object.fromEntries(Object.entries(memory).filter(([key]) => !clearedIds.has(key)));
  };

  if (currentPath[d] === pressed) {
    if (d === 0) {
      return { path: currentPath, memory, fold: true };
    }
    return { path: currentPath.slice(0, d), memory: clearSubtreeMemory(findPanelTabNode(tabs, validatedSelected), pressed), fold: false };
  }

  let path: readonly string[] = validatedSelected;
  let nextMemory: Record<string, string> = { ...memory };
  let tailNode = findPanelTabNode(tabs, path);
  while (tailNode && tailNode.kind === "branch") {
    const remembered = nextMemory[tailNode.id];
    if (!remembered) break;
    const child = tailNode.children.find((candidate) => candidate.id === remembered);
    if (!child) {
      const { [tailNode.id]: _stale, ...rest } = nextMemory;
      nextMemory = rest;
      break;
    }
    path = [...path, child.id];
    tailNode = child;
  }
  for (let i = 0; i < path.length - 1; i++) nextMemory[path[i]] = path[i + 1];
  return { path, memory: nextMemory, fold: false };
}

/** @emoji 🌱 Controlled/uncontrolled selection state shared by every {@link PanelTabBar} host ({@link Panel}, {@link PanelChromeTabBar}, {@link MobilePanel}). */
export interface PanelTabSelectionOptions {
  readonly tabs: readonly PanelTabNode[];
  readonly visible: boolean;
  /** @emoji 🎛 Fired when a tab press opens or folds the hosting surface (see {@link usePanelTabSelection}). */
  readonly onVisibleChange?: (visible: boolean) => void;
  readonly activeTabPath?: readonly string[];
  readonly onActiveTabPathChange?: (path: readonly string[]) => void;
  /** @emoji 🌱 Per-branch drill-down memory (see {@link progressPanelTabSelection}) — which child was last active under each branch, so returning to it restores the drill-down. */
  readonly pathMemory?: Readonly<Record<string, string>>;
  readonly onPathMemoryChange?: (memory: Readonly<Record<string, string>>) => void;
}

/**
 * 🌱 Shared fold/open/drill-down state machine for every {@link PanelTabBar} host: resolves the active path
 * against `tabs`, and interprets a raw tab press via {@link progressPanelTabSelection} — opening a closed host
 * on first press (swallowing that same press if it only re-selects the already-active leaf), folding it on an
 * active-root re-press, and otherwise advancing the path/memory (controlled when the matching `on*Change` is
 * given, else internal state). One instance of this state must back a single anchor's tabs, however many
 * hosts (panel chrome, navbar/footer chrome bar, mobile) render it — hosting is presentation-only.
 **/
export function usePanelTabSelection({ tabs, visible, onVisibleChange, activeTabPath, onActiveTabPathChange, pathMemory, onPathMemoryChange }: PanelTabSelectionOptions): {
  readonly resolvedPath: readonly string[];
  readonly memory: Readonly<Record<string, string>>;
  readonly handlePathChange: (raw: readonly string[]) => void;
} {
  const [internalActivePath, setInternalActivePath] = reactHostPort.useState<readonly string[]>(() => reconcileActivePath(tabs, [], panelTabChildren));
  const [internalMemory, setInternalMemory] = reactHostPort.useState<Readonly<Record<string, string>>>({});
  const memory = pathMemory ?? internalMemory;
  const resolvedPath = reactHostPort.useMemo(() => reconcileActivePath(tabs, activeTabPath ?? internalActivePath, panelTabChildren), [tabs, activeTabPath, internalActivePath]);

  const handlePathChange = (raw: readonly string[]) => {
    if (!visible) {
      onVisibleChange?.(true);
      if (raw[raw.length - 1] === resolvedPath[raw.length - 1]) return;
    }
    const result = progressPanelTabSelection(tabs, resolvedPath, raw, memory);
    if (visible && result.fold) {
      onVisibleChange?.(false);
      return;
    }
    if (onActiveTabPathChange) {
      onActiveTabPathChange(result.path);
    } else {
      setInternalActivePath(result.path);
    }
    if (onPathMemoryChange) {
      onPathMemoryChange(result.memory);
    } else {
      setInternalMemory(result.memory);
    }
  };

  return { resolvedPath, memory, handlePathChange };
}

/** @emoji 🗄️ Full arrangement of tabs across all eight anchors — the pure, draggable dock model. */
export interface PanelDock {
  readonly anchors: Record<Anchor, readonly PanelTabNode[]>;
}

function panelTabNodeToSkeleton(node: PanelTabNode): DockTabSkeleton {
  if (node.kind === "branch") return { id: node.id, children: node.children.map(panelTabNodeToSkeleton) };
  return node.trees.length > 0 ? { id: node.id, trees: node.trees.map((unit) => unit.id) } : { id: node.id };
}

/** @emoji 🗄️ Reduces a full {@link PanelDock} to the id-only {@link DockSkeleton} persisted across sessions. */
export function dockSkeletonOf(dock: PanelDock): DockSkeleton {
  const anchors = {} as Record<Anchor, readonly DockTabSkeleton[]>;
  for (const anchor of ANCHORS) anchors[anchor] = dock.anchors[anchor].map(panelTabNodeToSkeleton);
  return { version: 3, anchors };
}

function dockTabSkeletonsEqual(a: DockTabSkeleton, b: DockTabSkeleton): boolean {
  if (a.id !== b.id) return false;
  const aChildren = a.children ?? [];
  const bChildren = b.children ?? [];
  if (aChildren.length !== bChildren.length || !aChildren.every((child, index) => dockTabSkeletonsEqual(child, bChildren[index]!))) return false;
  const aTrees = a.trees ?? [];
  const bTrees = b.trees ?? [];
  return aTrees.length === bTrees.length && aTrees.every((id, index) => id === bTrees[index]);
}

/** @emoji 🗄️ Structural equality between two {@link DockSkeleton} values — used to decide whether an arrangement equals its computed default and therefore needs no persistence. */
export function dockSkeletonsEqual(a: DockSkeleton | null, b: DockSkeleton | null): boolean {
  if (a === b) return true;
  if (!a || !b) return false;
  return ANCHORS.every((anchor) => {
    const aTabs = a.anchors[anchor] ?? [];
    const bTabs = b.anchors[anchor] ?? [];
    return aTabs.length === bTabs.length && aTabs.every((tab, index) => dockTabSkeletonsEqual(tab, bTabs[index]!));
  });
}

/** @emoji 🗄️ Every node/unit in a default {@link PanelDock}, indexed by id, for identity-preserving reconciliation. */
function indexPanelDockById(dock: PanelDock): { readonly nodes: Map<string, PanelTabNode>; readonly units: Map<string, PanelTreeUnit> } {
  const nodes = new Map<string, PanelTabNode>();
  const units = new Map<string, PanelTreeUnit>();
  const visit = (node: PanelTabNode) => {
    nodes.set(node.id, node);
    if (node.kind === "branch") node.children.forEach(visit);
    else node.trees.forEach((unit) => units.set(unit.id, unit));
  };
  for (const anchor of ANCHORS) dock.anchors[anchor].forEach(visit);
  return { nodes, units };
}

/**
 * 🗄️ Rearranges (never reconstructs) `defaultDock`'s nodes/units to match a persisted {@link DockSkeleton} diff:
 * ids the default no longer declares are dropped, a tab whose kind no longer matches its default shape falls back
 * to the default's own shape, and any default tab/unit the skeleton doesn't mention is appended at its default
 * location. Subtrees untouched by the skeleton keep their exact default object identity.
 **/
/** @emoji 🗄️ Collects every tab id and tree-unit id the skeleton explicitly mentions (across all anchors), gated by whether the corresponding default node's own kind agrees — a mismatched entry's `children`/`trees` are never recursed into. */
function collectDockSkeletonMentions(entries: readonly DockTabSkeleton[], nodes: ReadonlyMap<string, PanelTabNode>, tabIds: Set<string>, unitIds: Set<string>): void {
  for (const entry of entries) {
    tabIds.add(entry.id);
    const defaultNode = nodes.get(entry.id);
    if (defaultNode?.kind === "branch" && entry.children) collectDockSkeletonMentions(entry.children, nodes, tabIds, unitIds);
    if (defaultNode?.kind === "leaf" && entry.trees) entry.trees.forEach((id) => unitIds.add(id));
  }
}

/** @emoji 🗄️ True if `node` itself, or any node in its default subtree, is explicitly mentioned somewhere in the persisted skeleton — distinguishes "this whole branch was deliberately emptied out by a move" (some descendant reappears elsewhere) from "this branch is simply missing from a stale skeleton" (nothing under it is mentioned anywhere, safe to re-seed from defaults). */
function defaultSubtreeMentioned(node: PanelTabNode, mentionedTabIds: ReadonlySet<string>): boolean {
  if (mentionedTabIds.has(node.id)) return true;
  return node.kind === "branch" && node.children.some((child) => defaultSubtreeMentioned(child, mentionedTabIds));
}

export function applyDockSkeleton(defaultDock: PanelDock, skeleton: DockSkeleton | null): PanelDock {
  if (!skeleton) return defaultDock;
  const { nodes, units } = indexPanelDockById(defaultDock);
  // Mentions are collected up front across the WHOLE skeleton (not incrementally during resolution) so that which
  // anchor/branch gets processed first never affects which default children/units get auto-appended back — a tab
  // moved to an anchor processed later must not be reclaimed by its old branch's "append missing" pass.
  const mentionedTabIds = new Set<string>();
  const mentionedUnitIds = new Set<string>();
  for (const anchor of ANCHORS) collectDockSkeletonMentions(skeleton.anchors[anchor] ?? [], nodes, mentionedTabIds, mentionedUnitIds);
  const resolvedTabIds = new Set<string>(); // guards only against the same id appearing twice in the skeleton

  const resolveNode = (entry: DockTabSkeleton): PanelTabNode | null => {
    const defaultNode = nodes.get(entry.id);
    if (!defaultNode || resolvedTabIds.has(entry.id)) return null;
    resolvedTabIds.add(entry.id);
    if (defaultNode.kind === "branch") {
      if (!entry.children) return defaultNode;
      const explicit = entry.children.map(resolveNode).filter((node): node is PanelTabNode => node !== null);
      const appended = defaultNode.children.filter((child) => !defaultSubtreeMentioned(child, mentionedTabIds));
      appended.forEach((child) => resolvedTabIds.add(child.id));
      const merged = [...explicit, ...appended];
      const unchanged = merged.length === defaultNode.children.length && merged.every((child, index) => child === defaultNode.children[index]);
      return unchanged ? defaultNode : { ...defaultNode, children: merged };
    }
    if (!entry.trees) return defaultNode;
    const explicitUnits = entry.trees.map((id) => units.get(id)).filter((unit): unit is PanelTreeUnit => unit !== undefined);
    const appendedUnits = defaultNode.trees.filter((unit) => !mentionedUnitIds.has(unit.id));
    const mergedUnits = [...explicitUnits, ...appendedUnits];
    const unchanged = mergedUnits.length === defaultNode.trees.length && mergedUnits.every((unit, index) => unit === defaultNode.trees[index]);
    return unchanged ? defaultNode : { ...defaultNode, trees: mergedUnits };
  };

  const anchors = {} as Record<Anchor, readonly PanelTabNode[]>;
  for (const anchor of ANCHORS) {
    const explicit = (skeleton.anchors[anchor] ?? []).map(resolveNode).filter((node): node is PanelTabNode => node !== null);
    const defaultTabs = defaultDock.anchors[anchor];
    const appended = defaultTabs.filter((tab) => !defaultSubtreeMentioned(tab, mentionedTabIds));
    appended.forEach((tab) => resolvedTabIds.add(tab.id));
    const merged = [...explicit, ...appended];
    const unchanged = merged.length === defaultTabs.length && merged.every((tab, index) => tab === defaultTabs[index]);
    anchors[anchor] = unchanged ? defaultTabs : merged;
  }
  return { anchors };
}

/** @emoji ↔️ Insert-position indicator shown between tab buttons while a drag hovers a row. */
const panelTabInsertPreviewClass = "w-0.5 self-stretch rounded-full bg-accent shrink-0";

/** @emoji 📑 One tab button; a child component (not inlined in {@link PanelTabRow}'s `.map`) so it can call driver-aware hooks per tab. */
const PanelTabButton: React.FC<{
  readonly tab: PanelTabNode;
  readonly variant: PanelTabBarVariant;
  readonly buttonClass: string;
  readonly tabSlot: string;
  readonly isActive: boolean;
  readonly showActiveColor: boolean;
  readonly stackIndex: number;
  readonly stackSize: number;
  readonly isDragSource: boolean;
  readonly isChildDropTarget: boolean;
  readonly isUnitDropReady: boolean;
  readonly anchor?: Anchor;
  readonly dock: PanelDockContextValue | null;
  readonly onSelect: (tabId: string) => void;
}> = ({ tab, variant, buttonClass, tabSlot, isActive, showActiveColor, stackIndex, stackSize, isDragSource, isChildDropTarget, isUnitDropReady, anchor, dock, onSelect }) => {
  const Icon = tab.icon;
  const inlineText = useControlInlineText(tab.id, tab.name);
  const surfaceDrag = useUiDriverDragSurface();
  const draggable = Boolean(anchor && dock);
  const windowTabChrome = variant === "panel";
  const inactiveTabChromeClass = windowTabChrome && stackIndex === stackSize - 1 ? modeDockInactiveTabBeforeGapClass : modeDockInactiveTabClass;
  return (
    <ChromeControlHint id={tab.id} text={tab.name}>
      <button
        data-slot={`${tabSlot}-tab-button`}
        data-hover-scope
        data-tab-id={tab.id}
        data-tab-kind={tab.kind}
        data-drag-source={isDragSource ? "true" : undefined}
        data-drop-nest={isChildDropTarget ? "true" : undefined}
        id={tab.id}
        data-active={isActive ? "true" : undefined}
        onClick={() => onSelect(tab.id)}
        onPointerDown={draggable && surfaceDrag ? (event) => dock!.startTabDrag(anchor!, tab.id, tab.name, event) : undefined}
        onDragOver={
          anchor && dock && tab.kind === "leaf"
            ? (event) => {
                if (event.dataTransfer.types.includes(PANEL_TREE_UNIT_MIME)) event.preventDefault();
              }
            : undefined
        }
        onDrop={
          anchor && dock && tab.kind === "leaf"
            ? (event) => {
                if (!event.dataTransfer.types.includes(PANEL_TREE_UNIT_MIME)) return;
                event.preventDefault();
                const session = readActivePanelTreeUnitDrag();
                if (!session) return;
                dock.onTreeUnitDockDrop({ unitId: session.unitId, fromTabId: session.tabId, target: { anchor, tabId: tab.id, index: Number.MAX_SAFE_INTEGER } });
                endPanelTreeUnitDrag();
              }
            : undefined
        }
        className={cn(
          windowTabChrome ? modeDockTabClassName : buttonClass,
          windowTabChrome && !isActive && inactiveTabChromeClass,
          windowTabChrome && isActive && showActiveColor && modeDockActiveTabClass,
          !windowTabChrome && isActive && showActiveColor && modeDockActiveTabFillClass,
          isDragSource && "opacity-40",
          isChildDropTarget && "ring-2 ring-accent",
          isUnitDropReady && dropZoneReadyClass,
        )}
      >
        {windowTabChrome ? (
          <div className={modeDockTabLabelClassName}>
            <Icon size={12} className="shrink-0" />
            {inlineText !== undefined ? <span className="truncate">{inlineText}</span> : null}
          </div>
        ) : (
          <>
            <span className={panelTabIconSlotClass}>
              <Icon size={12} />
            </span>
            {inlineText !== undefined ? <span className={panelTabLabelClass}>{inlineText}</span> : null}
          </>
        )}
        {draggable && !surfaceDrag ? <DragHandle onPointerDown={(event) => dock!.startTabDrag(anchor!, tab.id, tab.name, event)} onClick={(event) => event.stopPropagation()} emphasized={(isActive && showActiveColor) || isUnitDropReady} /> : null}
      </button>
    </ChromeControlHint>
  );
};

/** @emoji 📑 Props for {@link PanelTabRow}. */
interface PanelTabRowProps {
  readonly variant: PanelTabBarVariant;
  /** @emoji 🧲 Present only for {@link Panel} rows — enables drag-and-drop wiring via {@link usePanelDockContext}. */
  readonly anchor?: Anchor;
  readonly parentPath?: readonly string[];
  readonly tabs: readonly PanelTabNode[];
  readonly activeId?: string;
  readonly onSelect: (tabId: string) => void;
  /** @emoji 🎨 Paints the active tab's fill/border — off for a folded {@link Panel}, whose button group shouldn't claim a tab is "active" while nothing is showing. */
  readonly showActiveColor?: boolean;
  /** @emoji 🎀 Stacking direction from {@link PanelTabBar} — flips the row's divider to the content-facing side for `"panel"` variant. */
  readonly direction?: "up" | "down";
}

/** @emoji 📑 One row of sibling tabs; stacked by {@link PanelTabBar} into a {@link Ribbon}. */
const PanelTabRow: React.FC<PanelTabRowProps> = ({ variant, anchor, parentPath = [], tabs, activeId, onSelect, showActiveColor = true, direction = "down" }) => {
  const barRef = reactHostPort.useRef<HTMLDivElement>(null);
  const dock = usePanelDockContext();
  const tabSlot = variant === "mobile" ? "mobile-panel" : "panel";
  const sortedTabs = reactHostPort.useMemo(() => [...tabs].sort((a, b) => (a.order ?? 0) - (b.order ?? 0)), [tabs]);
  const resolvedActiveId = activeId;

  reactHostPort.useLayoutEffect(() => {
    const bar = barRef.current;
    if (!bar) return;
    bar.scrollLeft = 0;
    const activeButton = bar.querySelector<HTMLElement>(`[data-slot="${tabSlot}-tab-button"][data-active="true"]`);
    activeButton?.scrollIntoView({ block: "nearest", inline: "nearest" });
  }, [resolvedActiveId, sortedTabs, tabSlot]);

  const parentPathKey = parentPath.join("/");
  const setRowRef = reactHostPort.useCallback(
    (element: HTMLDivElement | null) => {
      barRef.current = element;
      if (anchor && dock) dock.registerTabRowDropTarget(anchor, parentPath, element);
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [anchor, dock, parentPathKey],
  );

  if (sortedTabs.length === 0) return null;

  const barClass = variant === "panel" ? panelAnchorTabBarClass(direction) : variant === "chrome" ? panelChromeTabBarClass : mobilePanelTabBarClass;
  const buttonClass = variant === "mobile" ? mobilePanelTabButtonClass : panelAnchorTabButtonClass;
  const dropTarget = dock?.dropTarget;
  const isDropRow = Boolean(anchor && dropTarget?.kind === "insert" && dropTarget.anchor === anchor && dropTarget.parentPath.length === parentPath.length && dropTarget.parentPath.every((id, index) => id === parentPath[index]));
  const dropInsertIndex = isDropRow && dropTarget?.kind === "insert" ? dropTarget.index : null;
  const tabDragActive = Boolean(dock?.dragTabId);
  const rowDropReady = tabDragActive && Boolean(anchor) && !parentPath.some((id) => dock?.draggedSubtreeIds?.has(id));
  const unitDragActive = usePanelTreeUnitDragActive();
  // 👻 Navbar/footer chrome toggles and folded panel root rows stay visible during canvas ghost; only open panel tab strips dim.
  const ghostDim = variant !== "chrome" && showActiveColor;

  return (
    <div ref={setRowRef} {...(ghostDim ? { "data-dim": true } : {})} data-slot={`${tabSlot}-tabs`} className={cn(barClass, rowDropReady && dropZoneReadyClass)}>
      {sortedTabs.map((tab, index) => {
        const isActive = tab.id === resolvedActiveId;
        const isDragSource = Boolean(anchor && dock?.dragTabId === tab.id);
        const isChildDropTarget = Boolean(anchor && dropTarget?.kind === "child" && dropTarget.anchor === anchor && dropTarget.parentId === tab.id);
        const isUnitDropReady = unitDragActive && Boolean(anchor) && tab.kind === "leaf";
        return (
          <React.Fragment key={tab.id}>
            {dropInsertIndex === index ? <div data-slot="panel-tab-insert-preview" aria-hidden className={panelTabInsertPreviewClass} /> : null}
            <PanelTabButton
              tab={tab}
              variant={variant}
              buttonClass={buttonClass}
              tabSlot={tabSlot}
              isActive={isActive}
              showActiveColor={showActiveColor}
              stackIndex={index}
              stackSize={sortedTabs.length}
              isDragSource={isDragSource}
              isChildDropTarget={isChildDropTarget}
              isUnitDropReady={isUnitDropReady}
              anchor={anchor}
              dock={dock}
              onSelect={onSelect}
            />
          </React.Fragment>
        );
      })}
      {dropInsertIndex === sortedTabs.length ? <div data-slot="panel-tab-insert-preview" aria-hidden className={panelTabInsertPreviewClass} /> : null}
    </div>
  );
};

/** @emoji 📑 Props for {@link PanelTabBar}. */
export interface PanelTabBarProps {
  readonly variant: PanelTabBarVariant;
  /** @emoji 🧲 Present only when hosted by a {@link Panel} under a {@link PanelDockProvider}. */
  readonly anchor?: Anchor;
  readonly tabs: readonly PanelTabNode[];
  readonly activePath: readonly string[];
  readonly onActivePathChange: (path: readonly string[]) => void;
  /** @emoji 🎀 Stacking direction for nested rows — `"up"` for bottom panels (rows grow toward the display center), `"down"` otherwise. */
  readonly direction?: "up" | "down";
  /** @emoji 🗜️ Skips rows above this depth without skipping the descent through them — pairs with a `"chrome"`-hosted root row rendered elsewhere (see {@link PanelChromeTabBar}) so the floating panel picks up at depth 1. */
  readonly startDepth?: number;
  /** @emoji 🗜️ Stops after this many emitted rows — `1` is the generalization of the old "root row only" (a folded {@link Panel}'s button group, or a chrome-hosted bar, both of which only ever show one row). */
  readonly maxRows?: number;
  /** @emoji 🎨 Paints the active tab's fill/border — off for a folded {@link Panel}, whose button group shouldn't claim a tab is "active" while nothing is showing. */
  readonly showActiveColor?: boolean;
}

/** @emoji 📑 Panel tab strip shared by {@link Panel}, {@link PanelChromeTabBar} and {@link MobilePanel} — one {@link PanelTabRow} per tree level (within `[startDepth, startDepth + maxRows)`), stacked in a {@link Ribbon}. */
export const PanelTabBar: React.FC<PanelTabBarProps> = ({ variant, anchor, tabs, activePath, onActivePathChange, direction = "down", startDepth = 0, maxRows = Infinity, showActiveColor = true }) => {
  const rows: RibbonRow[] = [];
  let level = tabs;
  let depth = 0;
  while (level.length > 0) {
    const sorted = [...level].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
    const activeId = sorted.some((tab) => tab.id === activePath[depth]) ? activePath[depth] : undefined;
    const rowDepth = depth;
    const parentPath = activePath.slice(0, rowDepth);
    if (depth >= startDepth) {
      rows.push({
        key: `${variant}-row-${rowDepth}`,
        content: (
          <PanelTabRow
            variant={variant}
            anchor={anchor}
            parentPath={parentPath}
            tabs={sorted}
            activeId={activeId}
            onSelect={(tabId) => onActivePathChange([...activePath.slice(0, rowDepth), tabId])}
            showActiveColor={showActiveColor}
            direction={direction}
          />
        ),
      });
      if (rows.length >= maxRows) break;
    }
    const active = activeId ? sorted.find((tab) => tab.id === activeId) : undefined;
    level = (active && panelTabChildren(active)) ?? [];
    depth++;
  }
  if (rows.length === 0) return null;
  return <Ribbon direction={direction} rows={rows} />;
};

// #region 🧲PanelDock
// Composable drag-and-drop: tabs dock between all eight anchors (pointer-capture drag, mirrors 🧭ModeDockDrag);
// tree units dock between leaf tabs (native HTML5 drag-and-drop, mirrors the window-template palette-drag session).

//#region 🔀Transforms

/** @emoji 🔀 True if `id` is `node.id` itself or belongs to one of its descendants. */
export function isPanelTabInSubtree(node: PanelTabNode, id: string): boolean {
  if (node.id === id) return true;
  return node.kind === "branch" && node.children.some((child) => isPanelTabInSubtree(child, id));
}

/** @emoji 🔀 Locates a tab anywhere in `dock`, returning its home anchor and the node itself. */
export function findPanelTabInDock(dock: PanelDock, id: string): { readonly anchor: Anchor; readonly node: PanelTabNode } | null {
  for (const anchor of ANCHORS) {
    const path = findPanelTabPath(dock.anchors[anchor], id);
    if (!path) continue;
    const node = findPanelTabNode(dock.anchors[anchor], path);
    if (node) return { anchor, node };
  }
  return null;
}

function collectPanelTabSubtreeIds(node: PanelTabNode, into: Set<string>): void {
  into.add(node.id);
  if (node.kind === "branch") node.children.forEach((child) => collectPanelTabSubtreeIds(child, into));
}

/** @emoji 🔀 Reassigns `order` to match array position — call after any transform that reorders a sibling array so the existing order-based sort renders the new arrangement. */
export function normalizePanelTabOrder(tabs: readonly PanelTabNode[]): readonly PanelTabNode[] {
  return tabs.map((tab, index) => (tab.order === index ? tab : { ...tab, order: index }));
}

/** @emoji 🔀 Recursively drops branch tabs left with zero children. The complementary half of "deliberately emptied" — keeping such branches out of {@link applyDockSkeleton}'s auto-append — is handled there by its subtree-mention check, so an emptied branch never resurfaces with default children restored. */
export function pruneEmptyPanelBranches(tabs: readonly PanelTabNode[]): readonly PanelTabNode[] {
  const pruned = tabs.map((tab) => (tab.kind === "branch" ? { ...tab, children: pruneEmptyPanelBranches(tab.children) } : tab)).filter((tab) => tab.kind !== "branch" || tab.children.length > 0);
  return pruned.length === tabs.length && pruned.every((tab, index) => tab === tabs[index]) ? tabs : pruned;
}

/** @emoji 🔀 Removes `id` wherever it lives in `tabs` (searching recursively into branches), pruning any ancestor branch left empty by the removal. Removal-first: callers compute insertion indices against this result, never the pre-removal tree. */
function removePanelTabFromSiblings(tabs: readonly PanelTabNode[], id: string): { readonly tabs: readonly PanelTabNode[]; readonly removed: PanelTabNode | null } {
  const directIndex = tabs.findIndex((tab) => tab.id === id);
  if (directIndex >= 0) {
    const removed = tabs[directIndex]!;
    return { tabs: normalizePanelTabOrder([...tabs.slice(0, directIndex), ...tabs.slice(directIndex + 1)]), removed };
  }
  for (let index = 0; index < tabs.length; index++) {
    const tab = tabs[index]!;
    if (tab.kind !== "branch") continue;
    const { tabs: nextChildren, removed } = removePanelTabFromSiblings(tab.children, id);
    if (!removed) continue;
    const next = nextChildren.length > 0 ? [...tabs.slice(0, index), { ...tab, children: nextChildren }, ...tabs.slice(index + 1)] : [...tabs.slice(0, index), ...tabs.slice(index + 1)];
    return { tabs: normalizePanelTabOrder(next), removed };
  }
  return { tabs, removed: null };
}

function insertPanelTabAtPath(tabs: readonly PanelTabNode[], parentPath: readonly string[], node: PanelTabNode, index: number): readonly PanelTabNode[] {
  if (parentPath.length === 0) {
    const clampedIndex = Math.max(0, Math.min(index, tabs.length));
    return normalizePanelTabOrder([...tabs.slice(0, clampedIndex), node, ...tabs.slice(clampedIndex)]);
  }
  const [headId, ...restPath] = parentPath;
  const headIndex = tabs.findIndex((tab) => tab.id === headId);
  if (headIndex < 0) return tabs;
  const head = tabs[headIndex]!;
  if (head.kind !== "branch") return tabs;
  const next = [...tabs];
  next[headIndex] = { ...head, children: insertPanelTabAtPath(head.children, restPath, node, index) };
  return next;
}

function appendPanelTabAsChild(tabs: readonly PanelTabNode[], parentId: string, node: PanelTabNode): readonly PanelTabNode[] {
  return tabs.map((tab) => {
    if (tab.id === parentId && tab.kind === "branch") return { ...tab, children: normalizePanelTabOrder([...tab.children, node]) };
    if (tab.kind === "branch") return { ...tab, children: appendPanelTabAsChild(tab.children, parentId, node) };
    return tab;
  });
}

/** @emoji 🎯 Where a dragged tab lands: `"insert"` places it among `parentPath`'s children at `index` (root when `parentPath` is empty); `"child"` appends it as the last child of the branch tab `parentId` (leaf targets never promote to branches in v1). */
export type PanelTabDockTarget = { readonly kind: "insert"; readonly anchor: Anchor; readonly parentPath: readonly string[]; readonly index: number } | { readonly kind: "child"; readonly anchor: Anchor; readonly parentId: string };

/** @emoji 🎯 A completed tab drag: move `tabId` (found via {@link findPanelTabInDock}, not `fromAnchor` alone) to `target`. */
export interface PanelTabDockMove {
  readonly tabId: string;
  readonly fromAnchor: Anchor;
  readonly target: PanelTabDockTarget;
}

/**
 * 🎯 Pure move transform: removes the dragged tab's subtree from wherever it lives and reinserts it at `target`.
 * Dropping a subtree into itself (as a child of one of its own descendants, or among the children of one) is a
 * no-operation returning the exact same {@link PanelDock} reference. Visibility is never touched here — the shell unfolds
 * a folded target anchor on drop.
 **/
export function moveTabInDock(dock: PanelDock, move: PanelTabDockMove): PanelDock {
  const located = findPanelTabInDock(dock, move.tabId);
  if (!located) return dock;
  const { anchor: fromAnchor, node } = located;
  const { target } = move;
  if (target.kind === "child" && isPanelTabInSubtree(node, target.parentId)) return dock;
  if (target.kind === "insert" && target.parentPath.some((id) => isPanelTabInSubtree(node, id))) return dock;

  const { tabs: sourceTabs, removed } = removePanelTabFromSiblings(dock.anchors[fromAnchor], move.tabId);
  if (!removed) return dock;

  const anchors: Record<Anchor, readonly PanelTabNode[]> = { ...dock.anchors, [fromAnchor]: sourceTabs };
  anchors[target.anchor] = target.kind === "child" ? appendPanelTabAsChild(anchors[target.anchor], target.parentId, removed) : insertPanelTabAtPath(anchors[target.anchor], target.parentPath, removed, target.index);
  return { anchors };
}

function replacePanelTabNode(tabs: readonly PanelTabNode[], id: string, nextNode: PanelTabNode): readonly PanelTabNode[] {
  return tabs.map((tab) => {
    if (tab.id === id) return nextNode;
    if (tab.kind === "branch") return { ...tab, children: replacePanelTabNode(tab.children, id, nextNode) };
    return tab;
  });
}

function replacePanelTabInDock(dock: PanelDock, id: string, nextNode: PanelTabNode): PanelDock {
  const located = findPanelTabInDock(dock, id);
  if (!located) return dock;
  const anchors = { ...dock.anchors };
  anchors[located.anchor] = replacePanelTabNode(dock.anchors[located.anchor], id, nextNode);
  return { anchors };
}

/** @emoji 🎯 Where a dragged tree unit lands: `tabId`'s (a leaf's) unit list, at `index`. */
export interface PanelTreeUnitDockTarget {
  readonly anchor: Anchor;
  readonly tabId: string;
  readonly index: number;
}

/** @emoji 🎯 A completed tree-unit drag from leaf `fromTabId` to `target`. */
export interface PanelTreeUnitDockMove {
  readonly unitId: string;
  readonly fromTabId: string;
  readonly target: PanelTreeUnitDockTarget;
}

/** @emoji 🎯 Pure move transform for tree units — reorders within a leaf's own unit list, or moves a unit from one leaf tab's list into another's. */
export function moveTreeUnitInDock(dock: PanelDock, move: PanelTreeUnitDockMove): PanelDock {
  const from = findPanelTabInDock(dock, move.fromTabId);
  if (!from || from.node.kind !== "leaf") return dock;
  const fromNode = from.node;
  const unit = fromNode.trees.find((candidate) => candidate.id === move.unitId);
  if (!unit) return dock;

  if (move.fromTabId === move.target.tabId) {
    const withoutUnit = fromNode.trees.filter((candidate) => candidate.id !== move.unitId);
    const clampedIndex = Math.max(0, Math.min(move.target.index, withoutUnit.length));
    const nextUnits = normalizePanelTreeUnitOrder([...withoutUnit.slice(0, clampedIndex), unit, ...withoutUnit.slice(clampedIndex)]);
    if (nextUnits.length === fromNode.trees.length && nextUnits.every((candidate, index) => candidate === fromNode.trees[index])) return dock;
    return replacePanelTabInDock(dock, move.fromTabId, { ...fromNode, trees: nextUnits });
  }

  const to = findPanelTabInDock(dock, move.target.tabId);
  if (!to || to.node.kind !== "leaf") return dock;
  const toNode = to.node;
  const fromNextUnits = normalizePanelTreeUnitOrder(fromNode.trees.filter((candidate) => candidate.id !== move.unitId));
  const clampedIndex = Math.max(0, Math.min(move.target.index, toNode.trees.length));
  const toNextUnits = normalizePanelTreeUnitOrder([...toNode.trees.slice(0, clampedIndex), unit, ...toNode.trees.slice(clampedIndex)]);
  const afterSource = replacePanelTabInDock(dock, move.fromTabId, { ...fromNode, trees: fromNextUnits });
  return replacePanelTabInDock(afterSource, move.target.tabId, { ...toNode, trees: toNextUnits });
}

function normalizePanelTreeUnitOrder(units: readonly PanelTreeUnit[]): readonly PanelTreeUnit[] {
  return units.map((unit, index) => (unit.order === index ? unit : { ...unit, order: index }));
}

//#endregion 🔀Transforms

//#region 🎯HitTesting

/** @emoji 🎯 A registered {@link PanelTabRow} drop surface — v1's drop surfaces are the base row of every anchor plus the rows along each anchor's current active path (branches not on the active path aren't visible, so aren't registered). */
export interface PanelTabRowDropTarget {
  readonly anchor: Anchor;
  readonly parentPath: readonly string[];
  readonly rowElement: HTMLElement;
}

function panelDockRowTabButtons(rowElement: HTMLElement, excludedIds: ReadonlySet<string>): HTMLElement[] {
  return [...rowElement.querySelectorAll<HTMLElement>("[data-tab-id]")].filter((element) => !excludedIds.has(element.dataset.tabId ?? ""));
}

/**
 * 🎯 Resolves a tab-drag drop target from registered rows. A row hit lands on a branch button's 30–70% center
 * band as `"child"` (nest into it), elsewhere as a midpoint `"insert"` — under a mirrored ({@link anchorHorizontal}
 * `"right"`) row the buttons render right-to-left, so the physical-fraction-to-model-index mapping inverts. Middle
 * anchors are never mirrored, so their buttons always render left-to-right.
 **/
export function computeTabDockDropZone(pointerX: number, pointerY: number, rows: readonly PanelTabRowDropTarget[], excludedIds: ReadonlySet<string>): PanelTabDockTarget | null {
  for (const row of rows) {
    const rect = row.rowElement.getBoundingClientRect();
    if (pointerX < rect.left || pointerX > rect.right || pointerY < rect.top || pointerY > rect.bottom) continue;
    const buttons = panelDockRowTabButtons(row.rowElement, excludedIds);
    const rtl = anchorHorizontal(row.anchor) === "right";
    for (let index = 0; index < buttons.length; index++) {
      const button = buttons[index]!;
      const buttonRect = button.getBoundingClientRect();
      if (pointerX < buttonRect.left || pointerX > buttonRect.right) continue;
      const fraction = buttonRect.width > 0 ? (pointerX - buttonRect.left) / buttonRect.width : 0.5;
      if (button.dataset.tabKind === "branch" && fraction > 0.3 && fraction < 0.7) {
        return { kind: "child", anchor: row.anchor, parentId: button.dataset.tabId! };
      }
      return { kind: "insert", anchor: row.anchor, parentPath: row.parentPath, index: index + (fraction >= 0.5 !== rtl ? 1 : 0) };
    }
    return { kind: "insert", anchor: row.anchor, parentPath: row.parentPath, index: buttons.length };
  }
  return null;
}

//#endregion 🎯HitTesting

//#region 🪟DragPreview

const DOCK_DRAG_CURSOR_OFFSET_X = 8;
const DOCK_DRAG_CURSOR_OFFSET_Y = 10;

/** @emoji 🪟 Floating label following the cursor while dragging a panel tab or tree unit. */
const DockDragChip: React.FC<{ readonly label: string; readonly x: number; readonly y: number }> = ({ label, x, y }) => (
  <div
    data-slot="dock-drag-chip"
    data-level="window"
    className={cn("pointer-events-none fixed z-tutorial flex max-w-[12rem] shrink-0 items-center gap-half rounded-sm border px-single py-half text-xs text-element shadow-md select-none", surfaceClass, borderNormalClass)}
    style={{ left: x + DOCK_DRAG_CURSOR_OFFSET_X, top: y + DOCK_DRAG_CURSOR_OFFSET_Y }}
  >
    <span className="truncate">{label}</span>
  </div>
);

//#endregion 🪟DragPreview

//#region 🌱TreeUnitDrag

/** @emoji 🌱 `dataTransfer` MIME identifying a tree-unit drag between leaf tabs. */
export const PANEL_TREE_UNIT_MIME = "application/x-semio-panel-tree-unit";

/** @emoji ↕️ `dataTransfer` MIME identifying a tree-section reorder drag within one {@link Tree}. */
export const TREE_SECTION_REORDER_MIME = "application/x-semio-tree-section-reorder";

export interface PanelTreeUnitDragSession {
  readonly tabId: string;
  readonly unitId: string;
  readonly label: string;
}

let activePanelTreeUnitDragSession: PanelTreeUnitDragSession | null = null;
const panelTreeUnitDragListeners = new Set<() => void>();

/** @emoji 🌱 Records the active tree-unit drag until drop or dragend. */
export function beginPanelTreeUnitDrag(session: PanelTreeUnitDragSession): void {
  activePanelTreeUnitDragSession = session;
  panelGhostSessionBridge?.begin(null);
  panelTreeUnitDragListeners.forEach((listener) => listener());
}

/** @emoji 🌱 Clears the active tree-unit drag session. */
export function endPanelTreeUnitDrag(): void {
  activePanelTreeUnitDragSession = null;
  panelGhostSessionBridge?.end();
  panelTreeUnitDragListeners.forEach((listener) => listener());
}

/** @emoji 🌱 Returns the in-flight tree-unit drag, if any. */
export function readActivePanelTreeUnitDrag(): PanelTreeUnitDragSession | null {
  return activePanelTreeUnitDragSession;
}

/** @emoji 🌱 True while a tree-unit drag is in flight — re-renders drop-zone consumers. */
export function usePanelTreeUnitDragActive(): boolean {
  return reactHostPort.useSyncExternalStore(
    (listener) => {
      panelTreeUnitDragListeners.add(listener);
      return () => panelTreeUnitDragListeners.delete(listener);
    },
    () => activePanelTreeUnitDragSession !== null,
    () => false,
  );
}

//#endregion 🌱TreeUnitDrag

//#region 🎛️Provider

interface PanelDockDragState {
  readonly anchor: Anchor;
  readonly tabId: string;
  readonly pointerId: number;
  readonly label: string;
  readonly x: number;
  readonly y: number;
}

interface PanelDockPendingDrag {
  readonly anchor: Anchor;
  readonly tabId: string;
  readonly pointerId: number;
  readonly label: string;
  readonly startX: number;
  readonly startY: number;
}

/** @emoji 🎛️ Business-free ui↔shell contract shared by every {@link Panel} under one {@link PanelDockProvider}. */
export interface PanelDockContextValue {
  readonly dragTabId: string | null;
  readonly draggedSubtreeIds: ReadonlySet<string> | null;
  readonly dropTarget: PanelTabDockTarget | null;
  readonly startTabDrag: (anchor: Anchor, tabId: string, label: string, event: React.PointerEvent<HTMLElement>) => void;
  readonly registerTabRowDropTarget: (anchor: Anchor, parentPath: readonly string[], element: HTMLElement | null) => void;
  readonly onTreeUnitDockDrop: (move: PanelTreeUnitDockMove) => void;
}

const PanelDockContext = reactHostPort.createContext<PanelDockContextValue | null>(null);

/** @emoji 🎛️ The enclosing {@link PanelDockProvider} contract, or `null` outside one (e.g. {@link MobilePanel}, which doesn't participate in the dock). */
export function usePanelDockContext(): PanelDockContextValue | null {
  return reactHostPort.useContext(PanelDockContext);
}

/** @emoji 🎛️ Props for {@link PanelDockProvider}. */
export interface PanelDockProviderProps {
  readonly dock: PanelDock;
  readonly onTabDockDrop: (move: PanelTabDockMove) => void;
  readonly onTreeUnitDockDrop: (move: PanelTreeUnitDockMove) => void;
  readonly children: React.ReactNode;
}

/** @emoji 🎛️ Wraps a layout's panels, wiring pointer-capture tab dragging (mirrors {@link Mode}'s window-tab drag) across all of them. Tree-unit drags are native HTML5 DnD and don't need this provider — see {@link beginPanelTreeUnitDrag}. */
export const PanelDockProvider: React.FC<PanelDockProviderProps> = ({ dock, onTabDockDrop, onTreeUnitDockDrop, children }) => {
  const panelGhost = usePanelGhost();
  const [pendingDrag, setPendingDrag] = reactHostPort.useState<PanelDockPendingDrag | null>(null);
  const [dragState, setDragState] = reactHostPort.useState<PanelDockDragState | null>(null);
  const [dropTarget, setDropTarget] = reactHostPort.useState<PanelTabDockTarget | null>(null);
  const dropTargetRef = reactHostPort.useRef<PanelTabDockTarget | null>(null);
  const rowsRef = reactHostPort.useRef(new Map<string, PanelTabRowDropTarget>());
  const excludedIdsRef = reactHostPort.useRef<ReadonlySet<string>>(new Set());
  const dockRef = reactHostPort.useRef(dock);
  dockRef.current = dock;

  const registerTabRowDropTarget = reactHostPort.useCallback((anchor: Anchor, parentPath: readonly string[], element: HTMLElement | null) => {
    const key = `${anchor}:${parentPath.join("/")}`;
    if (!element) {
      rowsRef.current.delete(key);
      return;
    }
    rowsRef.current.set(key, { anchor, parentPath, rowElement: element });
  }, []);

  const refreshDropTarget = reactHostPort.useCallback((x: number, y: number) => {
    const zone = computeTabDockDropZone(x, y, [...rowsRef.current.values()], excludedIdsRef.current);
    dropTargetRef.current = zone;
    setDropTarget(zone);
  }, []);

  const startTabDrag = reactHostPort.useCallback((anchor: Anchor, tabId: string, label: string, event: React.PointerEvent<HTMLElement>) => {
    if (event.button !== 0) return;
    setPendingDrag({ anchor, tabId, pointerId: event.pointerId, label, startX: event.clientX, startY: event.clientY });
  }, []);

  reactHostPort.useEffect(() => {
    if (!pendingDrag && !dragState) return;
    const handleMove = (event: PointerEvent) => {
      const activePointerId = dragState?.pointerId ?? pendingDrag?.pointerId;
      if (activePointerId === undefined || event.pointerId !== activePointerId) return;
      if (pendingDrag && !dragState) {
        const distance = Math.hypot(event.clientX - pendingDrag.startX, event.clientY - pendingDrag.startY);
        if (distance < 6) return;
        const located = findPanelTabInDock(dockRef.current, pendingDrag.tabId);
        const subtreeIds = new Set<string>();
        if (located) collectPanelTabSubtreeIds(located.node, subtreeIds);
        excludedIdsRef.current = subtreeIds;
        panelGhost?.begin(null);
        setDragState({ anchor: pendingDrag.anchor, tabId: pendingDrag.tabId, pointerId: pendingDrag.pointerId, label: pendingDrag.label, x: event.clientX, y: event.clientY });
        setPendingDrag(null);
        refreshDropTarget(event.clientX, event.clientY);
        return;
      }
      if (!dragState) return;
      setDragState((prev) => (prev ? { ...prev, x: event.clientX, y: event.clientY } : prev));
      refreshDropTarget(event.clientX, event.clientY);
    };
    const handleUp = (event: PointerEvent) => {
      const activePointerId = dragState?.pointerId ?? pendingDrag?.pointerId;
      if (activePointerId === undefined || event.pointerId !== activePointerId) return;
      if (dragState && dropTargetRef.current) {
        onTabDockDrop({ tabId: dragState.tabId, fromAnchor: dragState.anchor, target: dropTargetRef.current });
      }
      panelGhost?.end();
      setDragState(null);
      setPendingDrag(null);
      dropTargetRef.current = null;
      setDropTarget(null);
    };
    document.addEventListener("pointermove", handleMove);
    document.addEventListener("pointerup", handleUp);
    return () => {
      document.removeEventListener("pointermove", handleMove);
      document.removeEventListener("pointerup", handleUp);
    };
  }, [pendingDrag, dragState, onTabDockDrop, panelGhost, refreshDropTarget]);

  reactHostPort.useEffect(() => {
    if (!dragState) return;
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      panelGhost?.end();
      setDragState(null);
      setPendingDrag(null);
      dropTargetRef.current = null;
      setDropTarget(null);
    };
    document.addEventListener("keydown", handleKeyDown, true);
    return () => document.removeEventListener("keydown", handleKeyDown, true);
  }, [dragState, panelGhost]);

  const contextValue = reactHostPort.useMemo<PanelDockContextValue>(
    () => ({ dragTabId: dragState?.tabId ?? null, draggedSubtreeIds: dragState ? excludedIdsRef.current : null, dropTarget, startTabDrag, registerTabRowDropTarget, onTreeUnitDockDrop }),
    [dragState, dropTarget, startTabDrag, registerTabRowDropTarget, onTreeUnitDockDrop],
  );

  return (
    <PanelDockContext.Provider value={contextValue}>
      {children}
      {dragState ? <DockDragChip label={dragState.label} x={dragState.x} y={dragState.y} /> : null}
    </PanelDockContext.Provider>
  );
};

//#endregion 🎛️Provider

// #endregion 🧲PanelDock

//#region 🎛️PanelChromeTabBar

/** @emoji 🎛️ Props for {@link PanelChromeTabBar}: the anchor's own tab-selection state (see {@link usePanelTabSelection}) plus which anchor it drives. */
export interface PanelChromeTabBarProps extends PanelTabSelectionOptions {
  readonly anchor: Anchor;
  readonly className?: string;
}

/**
 * 🎛️ Hosts an anchor's root tab row inline in the navbar/footer chrome instead of on the floating panel — the
 * SAME {@link PanelTabBar} mechanism (progressive reveal, drill-down memory, drag-and-drop) as a panel-hosted
 * bar, just placed elsewhere. Renders nothing at rest once `tabs` is empty; becomes a drop target only while a
 * dock drag is in flight, mirroring {@link PanelEmptyDockZone}'s empty-anchor behavior. Pair with `Panel`'s
 * `tabBarHost="chrome"` for the matching anchor, and pass the SAME controlled selection props to both — chrome
 * hosting requires controlled state so the two hosts never fork.
 **/
export const PanelChromeTabBar: React.FC<PanelChromeTabBarProps> = ({ anchor, className = "", ...selection }) => {
  const dock = usePanelDockContext();
  const { resolvedPath, handlePathChange } = usePanelTabSelection(selection);
  const { tabs, visible } = selection;

  if (tabs.length === 0) {
    if (!dock?.dragTabId) return null;
    return (
      <LevelProvider level="panel">
        <GhostRegionShell sessionGhost={false} data-level="panel" data-slot="panel-chrome-tab-bar" data-anchor={anchor} className={cn("flex shrink-0 items-center", className)}>
          <PanelEmptyDockZone anchor={anchor} />
        </GhostRegionShell>
      </LevelProvider>
    );
  }

  return (
    <LevelProvider level="panel">
      <GhostRegionShell sessionGhost={false} data-level="panel" data-slot="panel-chrome-tab-bar" data-anchor={anchor} className={cn("flex shrink-0 items-center", className)}>
        <PanelTabBar variant="chrome" anchor={anchor} tabs={tabs} activePath={resolvedPath} onActivePathChange={handlePathChange} maxRows={1} showActiveColor={visible} />
      </GhostRegionShell>
    </LevelProvider>
  );
};

//#endregion 🎛️PanelChromeTabBar

/** @emoji 📑 Mobile panel tab strip height. */
export const mobilePanelTabBarClass = cn(panelTabBarClass, "h-large");

/** @emoji 📑 Mobile panel tab button padding. */
export const mobilePanelTabButtonClass = cn(panelTabButtonClass, "px-single");

/** @emoji ↔️ Accent stroke on the panel resize edge while hovered or dragging. */
export function panelResizeEdgeAccentClass(resizeSide: "left" | "right", active: boolean): string | undefined {
  if (!active) return undefined;
  switch (resizeSide) {
    case "left":
      return "border-l-accent";
    case "right":
      return "border-r-accent";
  }
}

/** @emoji 🪟 One chip span (stack-local x coordinates) on a silhouette edge. */
export interface WindowSilhouetteChip {
  readonly left: number;
  readonly right: number;
}

/** @emoji 🪟 One docked edge of a window silhouette (top or bottom cap). */
export interface WindowSilhouetteEdge {
  readonly depth: number;
  readonly chips: readonly WindowSilhouetteChip[];
}

/** @emoji 🪟 Measured window-chrome outline used by {@link windowSilhouettePath} / the SVG border overlay. */
export interface WindowSilhouetteMetrics {
  readonly width: number;
  readonly height: number;
  readonly top: WindowSilhouetteEdge;
  readonly bottom: WindowSilhouetteEdge;
}

/** @emoji 🪟 One vertex on the closed silhouette outline. */
export interface WindowSilhouettePoint {
  readonly x: number;
  readonly y: number;
}

/** @emoji 🪟 All border effects the silhouette SVG can paint. */
export const WINDOW_SILHOUETTE_BORDER_KINDS = ["celebrated", "introduced", "loading", "waiting", "active", "normal"] as const;

/** @emoji 🪟 Which border effect the dock-stack silhouette overlay should paint. */
export type WindowSilhouetteBorderKind = (typeof WINDOW_SILHOUETTE_BORDER_KINDS)[number];

/** @emoji 🪟 Whether an introduced stamp is the window chrome body itself (kind/instance scroll surface or
 * `[data-slot="window"]`), not a nested utility/action/tree row inside the pane. Window silhouette pulse
 * and the stack SVG border must follow only these stamps — introducing `transform` must pulse the utility
 * toggle, not the enclosing Top/Perspective silhouette. */
export function isWindowChromeIntroducedTarget(el: Element): boolean {
  if (el.getAttribute("data-slot") === "window") return true;
  const ids = [el.getAttribute("id") ?? "", ...(el.getAttribute("data-element-alias") ?? "").split(/\s+/)].filter(Boolean);
  for (const id of ids) {
    if (!id.startsWith("framework.window.")) continue;
    const rest = id.slice("framework.window.".length);
    if (!rest.includes(".")) return true;
  }
  return false;
}

/** @emoji 🪟 Resolves silhouette border kind from the active window + stack active flag.
 * Introduction stamps `data-introduced` on the window kind id target — often the inner scroll surface
 * (`framework.window.{kind}`), not `[data-slot="window"]` itself — so window-chrome descendants count.
 * Nested introduce targets (utilities, actions) must not promote the window silhouette. `celebrated`
 * (from `celebrateElements()`) is checked FIRST: it follows an introduced stamp being cleared on the
 * same target, and completion feedback must win during any overlap. */
export function resolveWindowSilhouetteBorderKind(windowEl: Element | null, stackActive = false): WindowSilhouetteBorderKind {
  if (windowEl?.getAttribute("data-celebrated") === "true") return "celebrated";
  if (windowEl) {
    for (const el of windowEl.querySelectorAll('[data-celebrated="true"]')) {
      if (isWindowChromeIntroducedTarget(el)) return "celebrated";
    }
  }
  if (windowEl?.getAttribute("data-introduced") === "true") return "introduced";
  if (windowEl) {
    for (const el of windowEl.querySelectorAll('[data-introduced="true"]')) {
      if (isWindowChromeIntroducedTarget(el)) return "introduced";
    }
  }
  const className = windowEl && typeof windowEl.className === "string" ? windowEl.className : "";
  if (/(?:^|\s)border-loading(?:-active|-element)?(?:\s|$)/.test(className)) return "loading";
  if (/(?:^|\s)border-waiting(?:-active|-element)?(?:\s|$)/.test(className)) return "waiting";
  return stackActive ? "active" : "normal";
}

/** @emoji 🪟 Hairline inset for {@link windowSilhouettePath}: a centered `--stroke-hairline` (1px) stroke
 * must sit fully inside the stack box. Half-pixel inset leaves the right/bottom halves on the exclusive
 * clip edge of `overflow: hidden` ancestors (resizable panels / mode body), so those sides vanish. */
export const WINDOW_SILHOUETTE_PATH_INSET = 1;

/** @emoji 🪟 Sub-pixel tolerance when clamping and merging measured chip spans. */
export const WINDOW_SILHOUETTE_CHIP_EPSILON = 0.5;

/** @emoji 🪟 Clamps chip spans into the silhouette box, drops empty spans, and merges overlaps. */
export function normalizeWindowSilhouetteChips(chips: readonly WindowSilhouetteChip[], x0: number, x1: number): WindowSilhouetteChip[] {
  const normalized = chips
    .map((chip) => ({
      left: Math.max(x0, Math.min(chip.left, x1)),
      right: Math.max(x0, Math.min(chip.right, x1)),
    }))
    .filter((chip) => chip.right - chip.left > WINDOW_SILHOUETTE_CHIP_EPSILON)
    .sort((a, b) => a.left - b.left);
  const merged: WindowSilhouetteChip[] = [];
  for (const chip of normalized) {
    const last = merged[merged.length - 1];
    if (!last || chip.left > last.right + WINDOW_SILHOUETTE_CHIP_EPSILON) merged.push({ ...chip });
    else last.right = Math.max(last.right, chip.right);
  }
  return merged;
}

/** @emoji 🪟 Walks one docked edge left-to-right; absent chip slots stay on the outer baseline. */
export function windowSilhouetteEdgePoints(edge: WindowSilhouetteEdge, x0: number, x1: number, outer: number, inner: number): WindowSilhouettePoint[] {
  const chips = normalizeWindowSilhouetteChips(edge.chips, x0, x1);
  if (edge.depth <= WINDOW_SILHOUETTE_CHIP_EPSILON || chips.length === 0) return [{ x: x0, y: outer }, { x: x1, y: outer }];
  let x = x0;
  let y = outer;
  const points: WindowSilhouettePoint[] = [{ x, y }];
  const push = (nextX: number, nextY: number) => {
    if (Math.abs(nextX - x) <= WINDOW_SILHOUETTE_CHIP_EPSILON && Math.abs(nextY - y) <= WINDOW_SILHOUETTE_CHIP_EPSILON) return;
    points.push({ x: nextX, y: nextY });
    x = nextX;
    y = nextY;
  };
  for (let i = 0; i < chips.length; i++) {
    const chip = chips[i]!;
    const hasNext = i < chips.length - 1;
    if (x < chip.right) push(chip.right, outer);
    const needsInnerTail = hasNext || chip.right < x1 - WINDOW_SILHOUETTE_CHIP_EPSILON;
    if (!needsInnerTail) continue;
    push(chip.right, inner);
    if (hasNext) {
      const nextLeft = chips[i + 1]!.left;
      if (chip.right < nextLeft - WINDOW_SILHOUETTE_CHIP_EPSILON) push(nextLeft, inner);
      push(nextLeft, outer);
    } else if (chip.right < x1 - WINDOW_SILHOUETTE_CHIP_EPSILON) {
      push(x1, inner);
    }
  }
  if (x < x1 - WINDOW_SILHOUETTE_CHIP_EPSILON && Math.abs(y - outer) <= WINDOW_SILHOUETTE_CHIP_EPSILON) push(x1, outer);
  return points;
}

/** @emoji 🪟 Walks one docked edge right-to-left; absent chip slots stay on the outer baseline. */
export function windowSilhouetteEdgePointsRtl(edge: WindowSilhouetteEdge, x0: number, x1: number, outer: number, inner: number): WindowSilhouettePoint[] {
  const chips = normalizeWindowSilhouetteChips(edge.chips, x0, x1);
  if (edge.depth <= WINDOW_SILHOUETTE_CHIP_EPSILON || chips.length === 0) return [{ x: x1, y: outer }, { x: x0, y: outer }];
  let x = x1;
  let y = outer;
  const points: WindowSilhouettePoint[] = [{ x, y }];
  const push = (nextX: number, nextY: number) => {
    if (Math.abs(nextX - x) <= WINDOW_SILHOUETTE_CHIP_EPSILON && Math.abs(nextY - y) <= WINDOW_SILHOUETTE_CHIP_EPSILON) return;
    points.push({ x: nextX, y: nextY });
    x = nextX;
    y = nextY;
  };
  for (let i = chips.length - 1; i >= 0; i--) {
    const chip = chips[i]!;
    const hasPrev = i > 0;
    if (x > chip.right) push(chip.right, y);
    const needsInnerTail = edge.depth > WINDOW_SILHOUETTE_CHIP_EPSILON;
    if (!needsInnerTail) continue;
    push(chip.right, inner);
    if (chip.right > chip.left + WINDOW_SILHOUETTE_CHIP_EPSILON) push(chip.left, inner);
    if (hasPrev) push(chip.left, outer);
    else if (chip.left > x0 + WINDOW_SILHOUETTE_CHIP_EPSILON) push(x0, inner);
  }
  if (x > x0 + WINDOW_SILHOUETTE_CHIP_EPSILON && Math.abs(y - outer) <= WINDOW_SILHOUETTE_CHIP_EPSILON) push(x0, outer);
  return points;
}

/** @emoji 🪟 Builds the closed silhouette outline (top LTR, right connector, bottom RTL, left connector). */
export function windowSilhouetteOutline(metrics: WindowSilhouetteMetrics, inset = WINDOW_SILHOUETTE_PATH_INSET): WindowSilhouettePoint[] {
  const w = Math.max(inset * 2, metrics.width);
  const h = Math.max(inset * 2, metrics.height);
  const x0 = inset;
  const y0 = inset;
  const x1 = w - inset;
  const y1 = h - inset;
  const topInner = Math.max(y0, Math.min(y0 + metrics.top.depth, y1));
  const bottomInner = Math.max(y0, Math.min(y1 - metrics.bottom.depth, y1));
  const top = windowSilhouetteEdgePoints(metrics.top, x0, x1, y0, topInner);
  const topEnd = top[top.length - 1] ?? { x: x1, y: y0 };
  const bottomSeed: WindowSilhouettePoint[] = topEnd.x === x1 && topEnd.y === y1 ? [] : [{ x: x1, y: y1 }];
  const bottom = windowSilhouetteEdgePointsRtl(metrics.bottom, x0, x1, y1, bottomInner);
  return simplifyWindowSilhouetteOutline([...top, ...bottomSeed, ...bottom]);
}

/** @emoji 🪟 Drops zero-length segments and collinear vertices from a closed outline loop. */
export function simplifyWindowSilhouetteOutline(points: readonly WindowSilhouettePoint[]): WindowSilhouettePoint[] {
  if (points.length <= 2) return [...points];
  const deduped: WindowSilhouettePoint[] = [];
  for (const point of points) {
    const last = deduped[deduped.length - 1];
    if (!last || Math.abs(last.x - point.x) > WINDOW_SILHOUETTE_CHIP_EPSILON || Math.abs(last.y - point.y) > WINDOW_SILHOUETTE_CHIP_EPSILON) deduped.push(point);
  }
  if (deduped.length <= 2) return deduped;
  const simplified: WindowSilhouettePoint[] = [];
  const count = deduped.length;
  for (let i = 0; i < count; i++) {
    const prev = deduped[(i - 1 + count) % count]!;
    const curr = deduped[i]!;
    const next = deduped[(i + 1) % count]!;
    const horizontal = Math.abs(prev.y - curr.y) <= WINDOW_SILHOUETTE_CHIP_EPSILON && Math.abs(curr.y - next.y) <= WINDOW_SILHOUETTE_CHIP_EPSILON;
    const vertical = Math.abs(prev.x - curr.x) <= WINDOW_SILHOUETTE_CHIP_EPSILON && Math.abs(curr.x - next.x) <= WINDOW_SILHOUETTE_CHIP_EPSILON;
    if (horizontal || vertical) continue;
    simplified.push(curr);
  }
  return simplified.length > 0 ? simplified : [...deduped];
}

/** @emoji 🪟 Returns broken outline invariants — empty when the path is clean. */
export function windowSilhouetteOutlineViolations(points: readonly WindowSilhouettePoint[], bounds?: { readonly x0: number; readonly y0: number; readonly x1: number; readonly y1: number }): string[] {
  if (points.length < 3) return ["outline requires at least three vertices"];
  const violations: string[] = [];
  const count = points.length;
  for (let i = 0; i < count; i++) {
    const prev = points[(i - 1 + count) % count]!;
    const curr = points[i]!;
    const next = points[(i + 1) % count]!;
    const dx = curr.x - prev.x;
    const dy = curr.y - prev.y;
    if (Math.abs(dx) <= WINDOW_SILHOUETTE_CHIP_EPSILON && Math.abs(dy) <= WINDOW_SILHOUETTE_CHIP_EPSILON) violations.push(`zero-length segment at vertex ${i}`);
    if (Math.abs(dx) > WINDOW_SILHOUETTE_CHIP_EPSILON && Math.abs(dy) > WINDOW_SILHOUETTE_CHIP_EPSILON) violations.push(`non-axis-aligned segment at vertex ${i}`);
    const ndx = next.x - curr.x;
    const ndy = next.y - curr.y;
    if (Math.abs(dx) > WINDOW_SILHOUETTE_CHIP_EPSILON && Math.abs(ndx) > WINDOW_SILHOUETTE_CHIP_EPSILON && Math.sign(dx) !== Math.sign(ndx)) violations.push(`horizontal reversal at vertex ${i}`);
    if (Math.abs(dy) > WINDOW_SILHOUETTE_CHIP_EPSILON && Math.abs(ndy) > WINDOW_SILHOUETTE_CHIP_EPSILON && Math.sign(dy) !== Math.sign(ndy)) violations.push(`vertical reversal at vertex ${i}`);
    const horizontal = Math.abs(prev.y - curr.y) <= WINDOW_SILHOUETTE_CHIP_EPSILON && Math.abs(curr.y - next.y) <= WINDOW_SILHOUETTE_CHIP_EPSILON;
    const vertical = Math.abs(prev.x - curr.x) <= WINDOW_SILHOUETTE_CHIP_EPSILON && Math.abs(curr.x - next.x) <= WINDOW_SILHOUETTE_CHIP_EPSILON;
    if (horizontal || vertical) violations.push(`collinear vertex at ${i}`);
    if (bounds) {
      if (curr.x < bounds.x0 - WINDOW_SILHOUETTE_CHIP_EPSILON || curr.x > bounds.x1 + WINDOW_SILHOUETTE_CHIP_EPSILON || curr.y < bounds.y0 - WINDOW_SILHOUETTE_CHIP_EPSILON || curr.y > bounds.y1 + WINDOW_SILHOUETTE_CHIP_EPSILON) {
        violations.push(`vertex ${i} outside bounds`);
      }
    }
  }
  return violations;
}

/** @emoji 🪟 Serializes a closed outline to an axis-aligned SVG path. */
export function windowSilhouettePathFromOutline(points: readonly WindowSilhouettePoint[]): string {
  if (points.length === 0) return "";
  const parts: string[] = [`M${points[0]!.x},${points[0]!.y}`];
  for (let i = 1; i < points.length; i++) {
    const prev = points[i - 1]!;
    const curr = points[i]!;
    if (Math.abs(curr.x - prev.x) > WINDOW_SILHOUETTE_CHIP_EPSILON) parts.push(`H${curr.x}`);
    if (Math.abs(curr.y - prev.y) > WINDOW_SILHOUETTE_CHIP_EPSILON) parts.push(`V${curr.y}`);
  }
  parts.push("Z");
  return parts.join(" ");
}

/** @emoji 🪟 Closed SVG path for the window outer silhouette. */
export function windowSilhouettePath(metrics: WindowSilhouetteMetrics, inset = WINDOW_SILHOUETTE_PATH_INSET): string {
  return windowSilhouettePathFromOutline(windowSilhouetteOutline(metrics, inset));
}

/** @emoji 🪟 Maps a silhouette border kind to stroke classes and color tokens. */
export function windowSilhouetteBorderPaint(kind: WindowSilhouetteBorderKind): { readonly className: string; readonly stroke: string } {
  switch (kind) {
    case "celebrated":
      return { className: "window-silhouette-border window-silhouette-border-celebrated-mask", stroke: "white" };
    case "introduced":
      return { className: "window-silhouette-border window-silhouette-border-introduced", stroke: "var(--introduced-border-color, var(--color-secondary))" };
    case "loading":
      return { className: "window-silhouette-border window-silhouette-border-loading", stroke: "var(--loading-border-color, var(--border-normal-color))" };
    case "waiting":
      return { className: "window-silhouette-border window-silhouette-border-waiting", stroke: "var(--waiting-border-color, var(--border-normal-color))" };
    case "active":
      return { className: "window-silhouette-border window-silhouette-border-active", stroke: "var(--active-base)" };
    case "normal":
      return { className: "window-silhouette-border window-silhouette-border-normal", stroke: "var(--border-normal-color)" };
  }
}

const WINDOW_CHROME_GAP_SELECTOR = '[data-slot="window-chrome-gap"], [data-slot="mode-dock-tab-gap"]';
const WINDOW_CHROME_CONTROLS_SELECTOR = '[data-slot="window-chrome-controls"], [data-slot="mode-dock-controls-cap"]';
const WINDOW_CHROME_CAP_SELECTOR = '[data-slot="window-chrome-cap"], [data-slot="mode-dock-tabbar"]';
const WINDOW_CHROME_FOOTER_SELECTOR = '[data-slot="window-chrome-footer"]';
const WINDOW_CHROME_FOOTER_GAP_SELECTOR = '[data-slot="window-chrome-footer-gap"], [data-slot="window-chrome-footer-gap-left"], [data-slot="window-chrome-footer-gap-right"]';
const WINDOW_CHROME_FOOTER_LEFT_SELECTOR = '[data-slot="window-chrome-footer-left"]';
const WINDOW_CHROME_FOOTER_CENTER_SELECTOR = '[data-slot="window-chrome-footer-center-chip"]';
const WINDOW_CHROME_FOOTER_RIGHT_SELECTOR = '[data-slot="window-chrome-footer-right"]';

/** @emoji 🪟 Reads live silhouette metrics from a mounted window-chrome stack (gap + controls). */
export function measureWindowSilhouetteMetrics(stack: HTMLElement): WindowSilhouetteMetrics | null {
  const stackRect = stack.getBoundingClientRect();
  const width = stackRect.width;
  const height = stackRect.height;
  if (width <= 0 || height <= 0) return null;
  const gap = stack.querySelector<HTMLElement>(WINDOW_CHROME_GAP_SELECTOR);
  const controls = stack.querySelector<HTMLElement>(WINDOW_CHROME_CONTROLS_SELECTOR);
  const tabBar = stack.querySelector<HTMLElement>(WINDOW_CHROME_CAP_SELECTOR);
  const gapRect = gap?.getBoundingClientRect();
  const controlsRect = controls?.getBoundingClientRect();
  const tabBarRect = tabBar?.getBoundingClientRect();
  const topChips: WindowSilhouetteChip[] = [];
  if (gapRect && gapRect.left - stackRect.left > WINDOW_SILHOUETTE_CHIP_EPSILON) topChips.push({ left: 0, right: gapRect.left - stackRect.left });
  if (controlsRect && stackRect.right - controlsRect.left > WINDOW_SILHOUETTE_CHIP_EPSILON) topChips.push({ left: controlsRect.left - stackRect.left, right: width });
  const topDepth = tabBarRect?.height || gapRect?.height || controlsRect?.height || 0;
  const footer = stack.querySelector<HTMLElement>(WINDOW_CHROME_FOOTER_SELECTOR);
  const footerLeft = stack.querySelector<HTMLElement>(WINDOW_CHROME_FOOTER_LEFT_SELECTOR);
  const footerCenter = stack.querySelector<HTMLElement>(WINDOW_CHROME_FOOTER_CENTER_SELECTOR);
  const footerRight = stack.querySelector<HTMLElement>(WINDOW_CHROME_FOOTER_RIGHT_SELECTOR);
  const bottomChips: WindowSilhouetteChip[] = [];
  let bottomDepth = 0;
  if (footer && (footerLeft || footerCenter || footerRight)) {
    const footerLeftRect = footerLeft?.getBoundingClientRect();
    const footerCenterRect = footerCenter?.getBoundingClientRect();
    const footerRightRect = footerRight?.getBoundingClientRect();
    if (footerLeftRect) bottomChips.push({ left: footerLeftRect.left - stackRect.left, right: footerLeftRect.right - stackRect.left });
    if (footerCenterRect) bottomChips.push({ left: footerCenterRect.left - stackRect.left, right: footerCenterRect.right - stackRect.left });
    if (footerRightRect) bottomChips.push({ left: footerRightRect.left - stackRect.left, right: footerRightRect.right - stackRect.left });
    bottomDepth = Math.max(footerLeftRect?.height ?? 0, footerCenterRect?.height ?? 0, footerRightRect?.height ?? 0);
  }
  return {
    width,
    height,
    top: { depth: topDepth, chips: topChips },
    bottom: { depth: bottomDepth, chips: bottomChips },
  };
}

/** @emoji 📏 Tab/gap/controls cells stay transparent; glass lives on the tabbar. Borders owned by {@link ModeDockStackSilhouetteBorder}. */
export const windowCapFrameClass = "relative z-[2] border-0 bg-transparent";

/** @emoji 📏 Active stack reuses the same transparent cell; outline color comes from the silhouette SVG. */
export const windowCapFrameActiveClass = windowCapFrameClass;

/** @emoji 🪟 Gap cutout is frosted via the parent tabbar glass, not a second ribbon. */
export const windowGapFrameClass = "border-0 bg-transparent";

/** @emoji 🪟 Active gap — same transparent cell; silhouette SVG paints the notch baseline. */
export const windowGapFrameActiveClass = windowGapFrameClass;

/** @emoji 📏 Body fill only — outer stroke is the stack silhouette SVG (tabs + cutout + controls + body); base level (mode body / floor windows float on) — host element must also carry `data-level="base"`. */
export const windowBodyFrameClass = cn("relative border-0", surfaceClass);

/** @emoji 📏 Active body fill — outline via silhouette SVG `data-kind="active"`. */
export const windowBodyFrameActiveClass = windowBodyFrameClass;

/** @emoji 📐 Grid tracks for multi-tab active chrome: one column per tab, then flex gap, then controls. */
export interface ModeDockChromeGrid {
  readonly templateColumns: string;
  readonly activeCol: number;
  readonly gapCol: number;
  readonly controlsCol: number;
  readonly bodyColumnSpan: string;
  readonly activeTabIndex: number;
  readonly tabCol: (tabIndex: number) => number;
}

/** @emoji 📐 Computes {@link ModeDockChromeGrid} column indices for a tab stack. */
export function modeDockChromeGridPlacement(tabs: readonly { id: string; title: string }[], activeId: string | undefined): ModeDockChromeGrid {
  const activeTabIndex = Math.max(
    0,
    tabs.findIndex((tab) => tab.id === activeId),
  );
  const gapCol = tabs.length + 1;
  const controlsCol = tabs.length + 2;
  const activeCol = activeTabIndex + 1;
  const templateParts = [...tabs.map(() => "max-content"), "minmax(0, 1fr)", "max-content"];
  return {
    templateColumns: templateParts.join(" "),
    activeCol,
    gapCol,
    controlsCol,
    bodyColumnSpan: `${activeCol} / ${gapCol + 1}`,
    activeTabIndex,
    tabCol: (tabIndex) => tabIndex + 1,
  };
}

/** @emoji 📏 Inactive sibling tab — normal pill resting on the U-frame baseline (window level, inherited from the ancestor {@link ModeDockStack} `data-level="window"` stamp). */
export const modeDockInactiveTabClass = cn(`relative z-30 box-border min-h-medium shrink-0`, surfaceClass);

/** @emoji 📏 Inactive tab before gap — inner divider only; outer stroke owned by the silhouette SVG. */
export const modeDockInactiveTabBeforeGapClass = cn(`relative z-30 box-border min-h-medium shrink-0`, surfaceClass);

/** @emoji 🪟 Icon + title cluster inside a mode-dock tab — standard gap between glyph and label. */
export const modeDockTabLabelClassName = "flex min-w-0 flex-1 items-center gap-single overflow-hidden";

/** @emoji 🪟 Default mode-dock tab label — element gray; emphasize on hover/active only. */
export const modeDockTabClassName = cn("group flex max-w-[12rem] shrink-0 cursor-pointer items-center px-single text-xs text-element select-none transition-colors", hoverExcludingHandleBgFillClass, hoverExcludingHandleTextEmphasizedClass);

/** @emoji 🪧 Static shell title (navbar app label, pane headings) — element gray at rest. */
export const shellChromeTitleClassName = "truncate text-sm font-medium text-element";

/** @emoji 🪧 Uppercase shell section title — element gray at rest. */
export const shellChromeSectionTitleClassName = "text-2xs font-semibold uppercase tracking-wide text-element";

/** @emoji 📏 Globally active dock tab — primary fill + emphasized label. */
export const modeDockActiveTabFillClass = interactiveActiveFillClass;

/** @emoji 📏 Stack-active tab fill — outline owned by the stack silhouette SVG. */
export const modeDockActiveTabClass = `relative z-20 box-border min-h-medium shrink-0 border-0 ${modeDockActiveTabFillClass}`;

/** @emoji 📏 Maximize/controls glass cell — transparent; tabbar owns the ribbon. */
export const windowControlsCapClass = "relative z-[2] flex shrink-0 items-stretch border-0 bg-transparent text-element";

/** @emoji 📏 Active controls cap — same transparent cell; silhouette SVG carries the active stroke. */
export const windowControlsCapActiveClass = windowControlsCapClass;

/** @emoji 📏 Multi-tab controls cap — same transparent cell on the shared tabbar glass. */
export const windowControlsCapActiveSplitClass = "relative flex shrink-0 items-stretch border-0 bg-transparent text-element";

//#region 🪟WindowChrome

/** @emoji 🎯 Tracks which panel/pane surface last received pointer or focus — exclusive active stroke without `:focus-within` CSS. */
const surfaceActiveRoots = new Set<HTMLElement>();
let surfaceActiveRoot: HTMLElement | null = null;
const surfaceActiveSubscribers = new Set<() => void>();
let surfaceActiveListenersInstalled = false;

function setSurfaceActiveRoot(next: HTMLElement | null): void {
  if (surfaceActiveRoot === next) return;
  surfaceActiveRoot = next;
  surfaceActiveSubscribers.forEach((notify) => notify());
}

function resolveSurfaceActiveRoot(target: Node): HTMLElement | null {
  let node: Node | null = target instanceof Element ? target : target.parentElement;
  let match: HTMLElement | null = null;
  while (node instanceof HTMLElement) {
    if (surfaceActiveRoots.has(node)) match = node;
    node = node.parentElement;
  }
  return match;
}

function installSurfaceActiveDocumentListeners(): void {
  if (surfaceActiveListenersInstalled || typeof document === "undefined") return;
  surfaceActiveListenersInstalled = true;
  const onPointerDown = (event: Event): void => {
    const target = event.target;
    if (!(target instanceof Node)) return;
    setSurfaceActiveRoot(resolveSurfaceActiveRoot(target));
  };
  const onFocusIn = (event: Event): void => {
    const target = event.target;
    if (!(target instanceof Node)) return;
    setSurfaceActiveRoot(resolveSurfaceActiveRoot(target));
  };
  document.addEventListener("pointerdown", onPointerDown);
  document.addEventListener("focusin", onFocusIn);
}

export interface SurfaceActiveBindProps {
  readonly onPointerDownCapture: () => void;
  readonly onFocusCapture: (event: React.FocusEvent) => void;
}

/** @emoji 🎯 True when this surface root was the last panel/pane to receive pointer or keyboard focus. */
export function useSurfaceActive(ref: React.RefObject<HTMLElement | null>): readonly [boolean, SurfaceActiveBindProps] {
  const [, bump] = reactHostPort.useState(0);
  reactHostPort.useLayoutEffect(() => {
    installSurfaceActiveDocumentListeners();
    const element = ref.current;
    if (!element) return;
    surfaceActiveRoots.add(element);
    const notify = (): void => bump((value) => value + 1);
    surfaceActiveSubscribers.add(notify);
    return () => {
      surfaceActiveRoots.delete(element);
      surfaceActiveSubscribers.delete(notify);
      if (surfaceActiveRoot === element) setSurfaceActiveRoot(null);
    };
  });
  const bind = reactHostPort.useMemo<SurfaceActiveBindProps>(
    () => ({
      onPointerDownCapture: () => {
        const root = ref.current;
        if (root) setSurfaceActiveRoot(root);
      },
      onFocusCapture: (event: React.FocusEvent) => {
        const root = ref.current;
        if (root?.contains(event.target as Node)) setSurfaceActiveRoot(root);
      },
    }),
    [ref],
  );
  return [ref.current !== null && surfaceActiveRoot === ref.current, bind] as const;
}

/** @emoji 🪟 Optional right-cap control on {@link WindowChrome} (enlarge / close). */
export interface WindowChromeControlAction {
  readonly id: string;
  readonly slot: string;
  readonly icon: React.ReactNode;
  readonly label: string;
  readonly onClick: () => void;
}

/** @emoji 🪟 Title chip in the window-chrome cap row (name + optional drag). */
export const windowChromeTitleChipClass = cn(modeDockTabClassName, surfaceClass, "relative z-30 box-border min-h-medium shrink-0 border", borderNormalClass);

export interface WindowChromeProps {
  readonly active?: boolean;
  readonly chipOnly?: boolean;
  readonly className?: string;
  readonly stackClassName?: string;
  readonly bodyClassName?: string;
  /** 🎈 Stamps `data-level={level}` on the chrome stack and wraps its content in a {@link LevelProvider}; cap/controls always render {@link glassChromeClass}, the body always renders {@link glassClass} — no longer configurable per-instance. */
  readonly level?: Level;
  readonly style?: React.CSSProperties;
  readonly stackRef?: React.Ref<HTMLDivElement>;
  readonly capRef?: React.Ref<HTMLDivElement>;
  readonly bodyRef?: React.Ref<HTMLDivElement>;
  readonly stackSlot?: string;
  readonly bodySlot?: string;
  readonly titleChips: React.ReactNode;
  readonly body?: React.ReactNode;
  readonly enlarge?: WindowChromeControlAction;
  readonly close?: WindowChromeControlAction;
  readonly gapProps?: React.HTMLAttributes<HTMLDivElement>;
  readonly footerLeftChips?: React.ReactNode;
  readonly footerCenterChips?: React.ReactNode;
  readonly footerRightChips?: React.ReactNode;
  readonly footerGapProps?: React.HTMLAttributes<HTMLDivElement>;
  readonly footerRef?: React.Ref<HTMLDivElement>;
  readonly introduceTarget?: Element | null;
  /** 🎓 Force silhouette border kind (e.g. introduction steps always pulse like `data-introduced`). */
  readonly borderKind?: WindowSilhouetteBorderKind;
  readonly stackDataAttrs?: Record<string, string | undefined>;
}

/** @emoji 🪟 SVG overlay that paints the U-cutout silhouette for any window-chrome stack. */
const WindowChromeSilhouetteBorder: React.FC<{
  readonly stack: HTMLElement | null;
  readonly active?: boolean;
  readonly introduceTarget?: Element | null;
  readonly borderKind?: WindowSilhouetteBorderKind;
  readonly silhouetteSlot?: string;
}> = ({ stack, active = false, introduceTarget, borderKind, silhouetteSlot = "window-chrome-silhouette-border" }) => {
  const [epoch, setEpoch] = reactHostPort.useState(0);
  const celebrateMaskId = `window-silhouette-celebrate-${reactHostPort.useId().replace(/:/g, "")}`;

  reactHostPort.useLayoutEffect(() => {
    if (!stack) return;
    const bump = () => setEpoch((value) => value + 1);
    bump();
    const resizeObserver = typeof ResizeObserver !== "undefined" ? new ResizeObserver(bump) : null;
    resizeObserver?.observe(stack);
    const mutationObserver = new MutationObserver(bump);
    mutationObserver.observe(stack, { attributes: true, subtree: true, childList: true });
    return () => {
      resizeObserver?.disconnect();
      mutationObserver.disconnect();
    };
  }, [stack]);

  const windowEl = stack?.querySelector('[data-slot="window"]') ?? introduceTarget ?? stack;
  const kind = resolveWindowSilhouetteBorderKind(windowEl, active);
  const resolvedKind =
    stack && [...stack.querySelectorAll('[data-celebrated="true"]')].some(isWindowChromeIntroducedTarget)
      ? "celebrated"
      : borderKind
        ? borderKind
        : stack && [...stack.querySelectorAll('[data-introduced="true"]')].some(isWindowChromeIntroducedTarget)
          ? "introduced"
          : kind;
  const metrics = stack ? measureWindowSilhouetteMetrics(stack) : null;
  void epoch;

  if (!metrics) {
    return <div data-slot={silhouetteSlot} data-window-silhouette-border data-kind={resolvedKind} data-pending="" aria-hidden className="pointer-events-none absolute inset-0 z-[40] overflow-visible" />;
  }
  const path = windowSilhouettePath(metrics);
  const paint = windowSilhouetteBorderPaint(resolvedKind);
  if (resolvedKind === "celebrated") {
    return (
      <svg data-slot={silhouetteSlot} data-window-silhouette-border data-kind={resolvedKind} className="pointer-events-none absolute inset-0 z-[40] overflow-visible" width={metrics.width} height={metrics.height} viewBox={`0 0 ${metrics.width} ${metrics.height}`} aria-hidden>
        <defs>
          <mask id={celebrateMaskId} maskUnits="userSpaceOnUse" x={0} y={0} width={metrics.width} height={metrics.height}>
            <rect x={0} y={0} width={metrics.width} height={metrics.height} fill="black" />
            <path d={path} fill="none" stroke={paint.stroke} strokeLinejoin="miter" vectorEffect="non-scaling-stroke" className={paint.className} />
          </mask>
        </defs>
        <foreignObject x={0} y={0} width={metrics.width} height={metrics.height} mask={`url(#${celebrateMaskId})`}>
          <div xmlns="http://www.w3.org/1999/xhtml" className="window-silhouette-border-celebrated-fill" style={{ width: "100%", height: "100%" }} />
        </foreignObject>
      </svg>
    );
  }
  return (
    <svg data-slot={silhouetteSlot} data-window-silhouette-border data-kind={resolvedKind} className="pointer-events-none absolute inset-0 z-[40] overflow-visible" width={metrics.width} height={metrics.height} viewBox={`0 0 ${metrics.width} ${metrics.height}`} aria-hidden>
      <path d={path} fill="none" stroke={paint.stroke} strokeLinejoin="miter" vectorEffect="non-scaling-stroke" className={paint.className} />
    </svg>
  );
};

/** @emoji 🪟 Shared U-cutout window chrome: left title chip(s), open gap, optional enlarge/close, continuous body border.
 * Cap glass lives only on the chip (+ controls) cells — never the full cap row — so the U-gap stays transparent
 * and shows whatever sits behind the stack (veil, canvas, page). Do not paint an absolute inset fill. */
export const WindowChrome = reactHostPort.forwardRef<HTMLDivElement, WindowChromeProps>(
  (
    {
      active = false,
      chipOnly = false,
      className,
      stackClassName,
      bodyClassName,
      level,
      style,
      stackRef,
      capRef,
      bodyRef,
      stackSlot = "window-chrome-stack",
      bodySlot = "window-chrome-body",
      titleChips,
      body,
      enlarge,
      close,
      gapProps,
      footerLeftChips,
      footerCenterChips,
      footerRightChips,
      footerGapProps,
      footerRef,
      introduceTarget,
      borderKind,
      stackDataAttrs,
    },
    ref,
  ) => {
    const [stackEl, setStackEl] = reactHostPort.useState<HTMLDivElement | null>(null);
    const setStackRef = reactHostPort.useCallback(
      (element: HTMLDivElement | null) => {
        setStackEl(element);
        if (typeof ref === "function") ref(element);
        else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = element;
        if (typeof stackRef === "function") stackRef(element);
        else if (stackRef) (stackRef as React.MutableRefObject<HTMLDivElement | null>).current = element;
      },
      [ref, stackRef],
    );

    const chipSurfaceClass = cn(windowCapFrameClass, glassChromeClass);
    const bodySurfaceClass = cn("relative border-0", glassClass);
    const controlsSurfaceClass = cn(windowControlsCapClass, glassChromeClass);
    const wrapLevel = (node: React.ReactNode): React.ReactNode => (level ? <LevelProvider level={level}>{node}</LevelProvider> : node);

    if (chipOnly) {
      return wrapLevel(
        <div ref={setStackRef} data-slot={stackSlot} data-window-silhouette data-level={level} className={cn("relative inline-flex min-w-0 bg-transparent", className, stackClassName)} style={style}>
          <div data-slot="window-chrome-chip-cap" data-window-silhouette-chip data-dock="top" data-ui-reveal-region="window-cap" className={cn("relative flex min-h-medium min-w-0 shrink items-stretch", chipSurfaceClass)}>
            {titleChips}
          </div>
        </div>,
      );
    }

    const { className: gapClassName, ...gapRest } = gapProps ?? {};
    const { className: footerGapClassName, ...footerGapRest } = footerGapProps ?? {};
    const hasFooter = Boolean(footerLeftChips || footerCenterChips || footerRightChips);
    const hasFooterGap = Boolean(footerLeftChips && footerRightChips && !footerCenterChips);
    const footerGapClass = cn("pointer-events-none relative min-h-0 min-w-0 bg-transparent", windowGapFrameClass, footerGapClassName);
    const footerChipClass = cn("relative flex min-h-medium min-w-0 shrink-0 items-stretch", chipSurfaceClass);
    return wrapLevel(
      <div
        ref={setStackRef}
        data-slot={stackSlot}
        data-window-silhouette
        data-level={level}
        data-active={active ? "true" : undefined}
        className={cn("relative flex min-h-0 min-w-0 flex-col overflow-visible bg-transparent text-foreground", stackClassName, className)}
        style={style}
        {...stackDataAttrs}
      >
        <WindowChromeSilhouetteBorder stack={stackEl} active={active} introduceTarget={introduceTarget} borderKind={borderKind} />
        <div ref={capRef} data-slot="window-chrome-cap" data-ui-reveal-region="window-cap" data-dim className="relative z-[2] flex w-full min-w-0 shrink-0 items-stretch bg-transparent">
          <div data-slot="window-chrome-chip-cap" data-window-silhouette-chip data-dock="top" className={cn("relative flex min-h-medium min-w-0 shrink items-stretch", chipSurfaceClass)}>
            {titleChips}
          </div>
          <div data-slot="window-chrome-gap" data-window-silhouette-gap aria-hidden {...gapRest} className={cn("pointer-events-none relative min-h-medium min-w-0 flex-1 bg-transparent", windowGapFrameClass, gapClassName)} />
          {enlarge || close ? (
            <div data-slot="window-chrome-controls" data-window-silhouette-chip data-dock="top" className={cn("relative z-[2] flex shrink-0 items-stretch", controlsSurfaceClass)}>
              {enlarge ? (
                <button
                  type="button"
                  id={enlarge.id}
                  data-slot={enlarge.slot}
                  className={cn("flex h-medium w-auto items-center justify-center border-0 bg-transparent transition-colors px-single gap-single text-element", interactiveHoverClass)}
                  onClick={enlarge.onClick}
                >
                  {enlarge.icon}
                  <span className="text-tiny whitespace-nowrap">{enlarge.label}</span>
                </button>
              ) : null}
              {close ? (
                <button
                  type="button"
                  id={close.id}
                  data-slot={close.slot}
                  className={cn("flex h-medium w-auto items-center justify-center border-0 bg-transparent transition-colors px-single gap-single text-element", interactiveHoverClass)}
                  onClick={close.onClick}
                >
                  {close.icon}
                  <span className="text-tiny whitespace-nowrap">{close.label}</span>
                </button>
              ) : null}
            </div>
          ) : null}
        </div>
        <div ref={bodyRef} data-slot={bodySlot} data-dim className={cn("relative z-10 min-h-0 flex-1", bodySurfaceClass, bodyClassName)}>
          {body}
        </div>
        {hasFooter ? (
          footerCenterChips ? (
            <div ref={footerRef} data-slot="window-chrome-footer" data-dim className="relative z-[2] grid w-full min-w-0 shrink-0 grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-end bg-transparent">
              <div data-slot="window-chrome-footer-gap-left" data-window-silhouette-gap {...footerGapRest} aria-hidden={footerLeftChips ? undefined : true} className={cn(footerGapClass, "justify-self-start")}>
                {footerLeftChips ? (
                  <div data-slot="window-chrome-footer-left" data-window-silhouette-chip data-dock="bottom" className={cn("pointer-events-auto", footerChipClass)}>
                    {footerLeftChips}
                  </div>
                ) : null}
              </div>
              <div data-slot="window-chrome-footer-center" className={cn(footerGapClass, "flex justify-center justify-self-center")}>
                <div data-slot="window-chrome-footer-center-chip" data-window-silhouette-chip data-dock="bottom" className={cn("pointer-events-auto", footerChipClass)}>
                  {footerCenterChips}
                </div>
              </div>
              <div data-slot="window-chrome-footer-gap-right" data-window-silhouette-gap aria-hidden={footerRightChips ? undefined : true} className={cn(footerGapClass, "justify-self-end")}>
                {footerRightChips ? (
                  <div data-slot="window-chrome-footer-right" data-window-silhouette-chip data-dock="bottom" className={cn("pointer-events-auto", footerChipClass)}>
                    {footerRightChips}
                  </div>
                ) : null}
              </div>
            </div>
          ) : (
            <div
              ref={footerRef}
              data-slot="window-chrome-footer"
              data-dim
              className={cn("relative z-[2] flex w-full min-w-0 shrink-0 items-stretch bg-transparent", footerLeftChips && !footerRightChips && "justify-start", footerRightChips && !footerLeftChips && "justify-end")}
            >
              {footerLeftChips ? (
                <div data-slot="window-chrome-footer-left" data-window-silhouette-chip data-dock="bottom" className={cn("relative flex min-h-medium min-w-0 shrink items-stretch", chipSurfaceClass)}>
                  {footerLeftChips}
                </div>
              ) : null}
              {hasFooterGap ? <div data-slot="window-chrome-footer-gap" data-window-silhouette-gap aria-hidden {...footerGapRest} className={cn(footerGapClass, "flex-1")} /> : null}
              {footerRightChips ? (
                <div data-slot="window-chrome-footer-right" data-window-silhouette-chip data-dock="bottom" className={cn("relative flex min-h-medium min-w-0 shrink items-stretch", chipSurfaceClass)}>
                  {footerRightChips}
                </div>
              ) : null}
            </div>
          )
        ) : null}
      </div>,
    );
  },
);
WindowChrome.displayName = "WindowChrome";

/** @emoji 🪟 Context menu with U-cutout chrome — title chip only, no enlarge/close; gap punches through. */
function ContextMenuChrome({ title, children, className, style }: { readonly title: string; readonly children: React.ReactNode; readonly className?: string; readonly style?: React.CSSProperties }): React.ReactElement {
  return (
    <WindowChrome
      active={false}
      level="menu"
      stackSlot="context-menu-content"
      className={contextMenuContentClassName(className)}
      style={style}
      titleChips={
        <div data-slot="context-menu-title-chip" className={windowChromeTitleChipClass}>
          <span className="truncate">{title}</span>
        </div>
      }
      body={children}
      bodyClassName="p-single"
    />
  );
}

